(function(A){Object.assign(A.D,{"G4487":{"l":"ῥῆμα","o":68,"ar":"<f><o>ῥῆμα</o>، <g>-τος, τό </g></f> <s n=\"1.\">أصلاً، عمّا يُقال أو يُنطَق، </s> <s n=\"(a)\"><b>كلمة</b>: <r v=\"Matt.27.14\"></r>، <r v=\"2Cor.12.4\"></r>؛ الجمع، <g>τὰ ῥ.</g>، عن الكلام والحديث، <r v=\"Luke.7.1\"></r>، <r v=\"John.8.20\"></r>، <r v=\"Acts.2.14\"></r>، <r v=\"Rom.10.18\"></r>، <r v=\"2Pet.3.2\"></r>، وفي مواضع أخرى؛ </s> <s n=\"(b)\">عكس <g>ὄνομα</g> (كلمة مفردة)، <b>قول، تصريح، كلمة</b> نبوة أو تعليم أو أمر: <r v=\"Matt.26.75\"></r>، <r v=\"Mark.9.32\"></r>، <r v=\"Luke.1.38\"></r> <r v=\"Luke.2.50\"></r>، <r v=\"Acts.11.16\"></r>، <r v=\"Rom.10.8\"></r>، <r v=\"Heb.11.3\"></r>؛ <g>ῥ. θεοῦ</g> (<g>κυρίου</g>)، <r v=\"Luke.3.2\"></r>، <r v=\"Acts.11.16\"></r>، <r v=\"Eph.6.17\"></r>، <r v=\"Heb.6.5\"></r> <r v=\"Heb.11.3\"></r>، <r v=\"1Pet.1.25\"></r> <i>(السبعينية)</i>؛ <g>τὰ ῥ. τ. θεοῦ</g>، <r v=\"John.3.34\"></r> <r v=\"John.8.47\"></r>؛ <g>ῥ. ἀργόν</g>، <r v=\"Matt.12.36\"></r>؛ <g>ῥ. ἄρρητα</g>، <r v=\"2Cor.12.4\"></r>. </s> <s n=\"2.\">مثل العبرية <h n=\"H1697\">דָּבָר</h>، عمّا هو موضوع الكلام، <b>شيء، أمر</b> (<r v=\"Gen.15.1\"></r>، <r v=\"Deut.17.8\"></r>، وفي مواضع أخرى): <r v=\"Luke.1.37\"></r> <r v=\"Luke.2.15\"></r>، <r v=\"Acts.10.37\"></r>؛ الجمع، <r v=\"Luke.1.65\"></r> <r v=\"Luke.2.19\"></r>، <r v=\"Luke.2.51\"></r>، <r v=\"Acts.5.32\"></r> <r v=\"Acts.13.42\"></r> </s>","en":"<f><o>ῥῆμα</o>, <g>-τος, τό </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1697\">דָּבָר</h>, also for <h n=\"H6310\">פֶּה</h>, and Aram. <h n=\"H6600\">פִּתְגָּם</h>, etc. ;] </e> </et> <s n=\"1.\">prop., of that which is said or spoken, </s> <s n=\"(a)\"><b>a word</b>: <r v=\"Matt.27.14\"></r>, <r v=\"2Cor.12.4\"></r>; pl., <g>τὰ ῥ.</g>, of speech, discourse, <r v=\"Luke.7.1\"></r>, <r v=\"John.8.20\"></r>, <r v=\"Acts.2.14\"></r>, <r v=\"Rom.10.18\"></r>, <r v=\"2Pet.3.2\"></r>, al.; </s> <s n=\"(b)\">opp. to <g>ὄνομα</g> (a single word), <b>a saying, statement, word</b> of prophecy, instruction or command (in cl., <i>phrase</i>): <r v=\"Matt.26.75\"></r>, <r v=\"Mark.9.32\"></r>, <r v=\"Luke.1.38\"></r> <r v=\"Luke.2.50\"></r>, <r v=\"Acts.11.16\"></r>, <r v=\"Rom.10.8\"></r>, <r v=\"Heb.11.3\"></r>; <g>ῥ. θεοῦ</g> (<g>κυρίου</g>), <r v=\"Luke.3.2\"></r>, <r v=\"Acts.11.16\"></r>, <r v=\"Eph.6.17\"></r>, <r v=\"Heb.6.5\"></r> <r v=\"Heb.11.3\"></r>, <r v=\"1Pet.1.25\"></r> <i>(LXX)</i>; <g>τὰ ῥ. τ. θεοῦ</g>, <r v=\"John.3.34\"></r> <r v=\"John.8.47\"></r>; <g>ῥ. ἀργόν</g>, <r v=\"Matt.12.36\"></r>;<g>ῥ. ἄρρητα</g>, <r v=\"2Cor.12.4\"></r>. </s> <s n=\"2.\">Like Heb.<h n=\"H1697\">דָּבָר</h> (but perh. also a Gk. colloquialism, v. Kennedy, <i>Sources</i>, 124; Thackeray, <i>Gr.</i>, 41), of that which is the subject of speech, <b>a thing, matter</b> (<r v=\"Gen.15.1\"></r>, <r v=\"Deut.17.8\"></r>, al.): <r v=\"Luke.1.37\"></r> <r v=\"Luke.2.15\"></r>, <r v=\"Acts.10.37\"></r>; pl., <r v=\"Luke.1.65\"></r> <r v=\"Luke.2.19\"></r>, <r v=\"Luke.2.51\"></r>, <r v=\"Acts.5.32\"></r> <r v=\"Acts.13.42\"></r> </s>"},"G4457":{"l":"πώρωσις","o":6,"ar":"<f>* <o>πώρωσις</o>، <g>-εως, ἡ</g></f> <s><b>تغطية بجلد متصلِّب (تكلُّس)</b>، <b>تقسية (غلاظة)</b>: مجازيًا، <r v=\"Mark.3.6\"></r>، <r v=\"Rom.11.25\"></r>، <r v=\"Eph.4.18\"></r>.†</s>","en":"<f>* <o>πώρωσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>πωρόω</g>),</e> </et> <s><b>a covering with a callus</b>, <b>a hardening</b>: metaph., <r v=\"Mark.3.6\"></r>, <r v=\"Rom.11.25\"></r>, <r v=\"Eph.4.18\"></r>.†</s>"},"G4413":{"l":"πρῶτος","o":154,"ar":"<f>ب. صيغة التفضيل العليا، <o>πρῶτος</o>، <g>-η, -ον</g>،</f> <s><b>أول</b>، <s n=\"1.\">عن الزمان أو المكان؛ <s n=\"(a)\">مطلقًا، بمعنى الاسم، <g>ὁ π.</g>، <r v=\"Luke.14.18\"></r>، <r v=\"John.19.32\"></r>، <r v=\"1Cor.14.30\"></r>؛ <g>ὁ π. καὶ ὁ ἔσχατος</g>، <r v=\"Rev.1.17\"></r> <r v=\"Rev.2.8\"></r> <r v=\"Rev.22.13\"></r>؛ المحايد، <g>τὸ π.</g>، عكس <g>τ. δεύτερον</g>، <r v=\"Heb.10.9\"></r>؛ <g>τὰ π.</g>، عكس <g>τ. ἔσχατα</g>، <r v=\"Matt.12.45\"></r>، <r v=\"Luke.11.26\"></r>، <r v=\"2Pet.2.20\"></r>؛ بدون أداة التعريف، <r v=\"Matt.10.2\"></r>؛ الجمع، <r v=\"Matt.19.30\"></r>، <r v=\"Mark.10.31\"></r>، <r v=\"Luke.13.30\"></r>؛ <g>ἐν πρώτοις</g> (الترجمات الإنجليزية: <i>أولاً وقبل كل شيء</i>)، <r v=\"1Cor.15.3\"></r>؛</s> <s n=\"(b)\">صفةً: <g>πρώτῃ</g> (أي <g>ἡμέρᾳ</g>) <g>σαββάτου</g>، <r v=\"Mark.16.9\"></r>؛ <g>φυλακή</g>، عكس <g>δευτέρα</g>، <r v=\"Acts.12.10\"></r>؛ وما يعادل الظرف في الإنجليزية، <r v=\"John.8.7\"></r> <r v=\"John.20.4\"></r>، <r v=\"John.20.8\"></r>، <r v=\"Acts.27.43\"></r>، <r v=\"Rom.10.19\"></r>، <r v=\"1Tim.1.16\"></r>، <r v=\"1John.4.19\"></r>؛ = <g>πρότερος</g> (انظر أدناه): مع المضاف إليه، <g>π. μου ἦν</g> (<i>رئيسي (المتقدّم عليّ)</i>)، <r v=\"John.1.15\"></r>، <r v=\"John.1.30\"></r>؛ مع أداة التعريف، <r v=\"Mark.14.12\"></r>، <r v=\"Acts.1.1\"></r>، وفي مواضع أخرى؛ يليه <g>ὁ δεύτερος</g>، إلخ، <r v=\"Matt.22.25\"></r>، <r v=\"Mark.12.20\"></r>، وفي مواضع أخرى.</s> </s> <s n=\"2.\">عن الرتبة أو المقام، <b>رئيس، أول</b>، <b>أعظم (رئيسي)</b>: <r v=\"Matt.20.27\"></r> <r v=\"Matt.22.38\"></r>، <r v=\"Mark.9.35\"></r>، <r v=\"Eph.6.2\"></r>، وفي مواضع أخرى؛ مع المضاف إليه، <r v=\"Mark.12.28\"></r>، <r v=\"Mark.12.29\"></r> وفي مواضع أخرى؛ <g>πόλις</g>، <r v=\"Acts.16.12\"></r>؛ مع أداة التعريف، <r v=\"Luke.15.22\"></r> <r v=\"Luke.19.47\"></r>، <r v=\"Acts.13.50\"></r>، وفي مواضع أخرى.</s> <s n=\"3.\">المحايد، <g>πρῶτον</g>، ظرفًا، <b>أولاً</b>، <b>في البداية</b>؛ <s n=\"(a)\">عن الزمان: <r v=\"Matt.8.21\"></r>، <r v=\"Mark.4.28\"></r>، وفي مواضع أخرى؛ <g>τὸ π.</g>، <r v=\"John.10.40\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">عن الترتيب: <r v=\"Rom.3.2\"></r>، <r v=\"1Cor.11.18\"></r>، وفي مواضع أخرى.</s> </s> </s>","en":"<f>B. Superl., <o>πρῶτος</o>, <g>-η, -ον</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7223\">רִאשׁוֹן</h>, also for <h n=\"H259\">אֶחַד</h>, etc.;]</e> </et> <s><b>first</b>, <s n=\"1.\">of Time or Place; <s n=\"(a)\">absol., as subst., <g>ὁ π.</g>., <r v=\"Luke.14.18\"></r>, <r v=\"John.19.32\"></r>, <r v=\"1Cor.14.30\"></r>; <g>ὁ π. καὶ ὁ ἔσχατος</g>, <r v=\"Rev.1.17\"></r> <r v=\"Rev.2.8\"></r> <r v=\"Rev.22.13\"></r>; neut., <g>τὸ π.</g>, opp. to <g>τ. δεύτερον</g>, <r v=\"Heb.10.9\"></r>; <g>τὰ π.</g>, opp. to <g>τ. ἔσχατα</g>, <r v=\"Matt.12.45\"></r>, <r v=\"Luke.11.26\"></r>, <r v=\"2Pet.2.20\"></r>; anarth., <r v=\"Matt.10.2\"></r>; pl., <r v=\"Matt.19.30\"></r>, <r v=\"Mark.10.31\"></r>, <r v=\"Luke.13.30\"></r>; <g>ἐν πρώτοις</g> (EV, <i>first of all</i>), <r v=\"1Cor.15.3\"></r>;</s> <s n=\"(b)\">as adj.: <g>πρώτῃ</g> (sc. <g>ἡμέρᾳ</g>) <g>σαββάτου</g>, <r v=\"Mark.16.9\"></r>; <g>φυλακή</g>, opp. to <g>δευτέρα</g>, <r v=\"Acts.12.10\"></r>; equiv. to adv. in English, <r v=\"John.8.7\"></r> <r v=\"John.20.4\"></r>, <r v=\"John.20.8\"></r>, <r v=\"Acts.27.43\"></r>, <r v=\"Rom.10.19\"></r>, <r v=\"1Tim.1.16\"></r>, <r v=\"1John.4.19\"></r>; = <g>πρότερος</g> (v. infr.; cf. M, <i>Pr.</i>, 79; Bl., § 11, 5; Thackeray, <i>Gr.</i>, 183 f.): c. gen., <g>π. μου ἦν</g> (<i>my chief</i>: Abbott, <i>Jg.</i>, 509 ff.; but cf. M, <i>Pr.</i>, 245), <r v=\"John.1.15\"></r>, <r v=\"John.1.30\"></r>; c. art., <r v=\"Mark.14.12\"></r>, <r v=\"Acts.1.1\"></r>, al.; seq. <g>ὁ δεύτερος</g>, etc., <r v=\"Matt.22.25\"></r>, <r v=\"Mark.12.20\"></r>, al.</s> </s> <s n=\"2.\">Of Rank or Dignity, <b>chief</b>, <b>principal</b>: <r v=\"Matt.20.27\"></r> <r v=\"Matt.22.38\"></r>, <r v=\"Mark.9.35\"></r>, <r v=\"Eph.6.2\"></r>, al.; c. gen., <r v=\"Mark.12.28\"></r>, <r v=\"Mark.12.29\"></r> al.; <g>πόλις</g> (Field, <i>Notes</i>, 124), <r v=\"Acts.16.12\"></r>; c. art., <r v=\"Luke.15.22\"></r> <r v=\"Luke.19.47\"></r>, <r v=\"Acts.13.50\"></r>, al.</s> <s n=\"3.\">Neut., <g>πρῶτον</g>, as adv., <b>first</b>, <b>at the first</b>; <s n=\"(a)\">of Time: <r v=\"Matt.8.21\"></r>, <r v=\"Mark.4.28\"></r>, al.; <g>τὸ π.</g>, <r v=\"John.10.40\"></r>, al.;</s> <s n=\"(b)\">of Order: <r v=\"Rom.3.2\"></r>, <r v=\"1Cor.11.18\"></r>, al.</s> </s> </s>"},"G4492":{"l":"ῥιζόω","o":2,"ar":"<f><o>ῥιζόω</o>، <g>-ῶ</g></f> <s><b>يجعله يتأصّل (يمدّ جذوره)</b>. مجازيًا، <b>يغرس، يثبِّت بقوة، يرسِّخ</b>: المبني للمجهول (الترجمات الإنجليزية: <i>متأصِّلون</i>)، <g>ἐν ἀγάπῃ</g>، <r v=\"Eph.3.18\"></r>؛ <g>ἐν Χριστῷ</g>، <r v=\"Col.2.7\"></r> (قارن <g>ἐκ</g> <g>ριζόω</g>).†</s>","en":"<f><o>ῥιζόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ῥίζα</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Isa.40.24\"></r>, <r v=\"Jer.12.2\"></r> (<h n=\"H8327\">שׁרשׁ</h>), <r v=\"Sir.3.28\"></r> <r v=\"Sir.24.12\"></r> * ;] </e> </et> <s><b>to cause to take root</b>. Metaph., <b>to plant, fix firmly, establish</b>: pass. (EV, <i>rooted</i>), <g>ἐν ἀγάπῃ</g>, <r v=\"Eph.3.18\"></r>; <g>ἐν Χριστῷ</g>, <r v=\"Col.2.7\"></r> (cf. <g>ἐκ</g> <g>ριζόω</g>).†</s>"},"G4459":{"l":"πῶς","o":100,"ar":"<f><o>πῶς</o>، ظرف استفهام، مقابل لـ <g>ὅπως</g>،</f> <s n=\"1.\">أصلاً، في الأسئلة المباشرة، <b>كيف؟</b>: مع الإخباري، <r v=\"Matt.12.29\"></r>، <r v=\"Mark.3.23\"></r>، <r v=\"Luke.11.18\"></r>، <r v=\"John.3.4\"></r>، وفي مواضع أخرى؛ <g>καὶ π.</g>، <r v=\"Mark.4.13\"></r>، <r v=\"Luke.20.44\"></r>؛ <g>π. οὖν</g>، <r v=\"Matt.12.26\"></r>؛ <g>π. οὐ</g>، <r v=\"Matt.16.11\"></r>، <r v=\"Luke.12.56\"></r>؛ في الأسئلة التداولية، مع صيغة الاحتمال، <r v=\"Matt.23.33\"></r> <r v=\"Matt.26.54\"></r>؛ <g>π. οὖν</g>، <r v=\"Rom.10.14\"></r>؛ <g>π. δέ</g>، <r v=\"Rom.10.14\"></r>، <r v=\"Rom.10.15\"></r>؛ يليه <g>ἄν</g> مع صيغة التمني، <r v=\"Acts.8.31\"></r>.</s> <s n=\"2.\">= <g>ὅπως</g>، <g>ὥς</g>؛ <s n=\"(a)\">في الكلام غير المباشر: مع الإخباري، <r v=\"Matt.6.28\"></r>، <r v=\"Mark.12.41\"></r>، <r v=\"Luke.8.36\"></r>، <r v=\"John.9.15\"></r>، <r v=\"Acts.9.27\"></r>، وفي مواضع أخرى؛ مع صيغة الاحتمال، <r v=\"Mark.11.18\"></r>، <r v=\"Luke.12.11\"></r>؛</s> <s n=\"(b)\">في التعجب: <r v=\"Matt.21.20\"></r>، <r v=\"Mark.10.23\"></r>، <r v=\"Mark.10.24\"></r>، <r v=\"Luke.12.50\"></r> <r v=\"Luke.18.24\"></r>، <r v=\"John.11.36\"></r>.</s> </s>","en":"<f><o>πῶς</o>, interrog. adv., correl. of <g>ὅπως</g>,</f> <s n=\"1.\">prop., in direct questions, <b>how?</b>: c. indic., <r v=\"Matt.12.29\"></r>, <r v=\"Mark.3.23\"></r>, <r v=\"Luke.11.18\"></r>, <r v=\"John.3.4\"></r>, al.; <g>καὶ π.</g>, <r v=\"Mark.4.13\"></r>, <r v=\"Luke.20.44\"></r>; <g>π. οὖν</g>, <r v=\"Matt.12.26\"></r>; <g>π. οὐ</g>, <r v=\"Matt.16.11\"></r>, <r v=\"Luke.12.56\"></r>; in deliberative questions (cf. Bl., § 64, 6), c. subjc., <r v=\"Matt.23.33\"></r> <r v=\"Matt.26.54\"></r>; <g>π. οὖν</g>, <r v=\"Rom.10.14\"></r>; <g>π. δέ</g>, <r v=\"Rom.10.14\"></r>, <r v=\"Rom.10.15\"></r>; seq. <g>ἄν</g>, c. optat., <r v=\"Acts.8.31\"></r>.</s> <s n=\"2.\">As sometimes in cl. but more freq. and increasingly so in late writers (v. WM, § 57, 2; Bl., § 70, 2; Thumb, <i>MGr.</i>, 192; Jannaris, <i>Gr.</i>, <i>App.</i>, vi, 13 f.), = <g>ὅπως</g>, <g>ὥς</g>; <s n=\"(a)\">in indirect discourse: c. indic., <r v=\"Matt.6.28\"></r>, <r v=\"Mark.12.41\"></r>, <r v=\"Luke.8.36\"></r>, <r v=\"John.9.15\"></r>, <r v=\"Acts.9.27\"></r>, al.; c. subjc., <r v=\"Mark.11.18\"></r>, <r v=\"Luke.12.11\"></r>;</s> <s n=\"(b)\">in exclamations: <r v=\"Matt.21.20\"></r>, <r v=\"Mark.10.23\"></r>, <r v=\"Mark.10.24\"></r>, <r v=\"Luke.12.50\"></r> <r v=\"Luke.18.24\"></r>, <r v=\"John.11.36\"></r>.</s> </s>"},"G4448":{"l":"πυρόω","o":6,"ar":"<f><o>πυρόω</o>، <g>-ῶ</g></f> <s><b>يُضرم نارًا</b>، <b>يُحرق تمامًا</b>. وفي العهد الجديد دائمًا بالمبني للمجهول، <s n=\"1.\"><b>يشتعل نارًا</b>، <b>يحترق (يلتهب)</b>: <r v=\"Eph.6.16\"></r>، <r v=\"2Pet.3.12\"></r>؛ اسم الفاعل، <b>متوهّج (محمًى)</b>، <r v=\"Rev.1.15\"></r>. مجازيًا، عن الحزن أو السخط، <r v=\"2Cor.11.29\"></r>؛ عن الشهوة، <r v=\"1Cor.7.9\"></r>.</s> <s n=\"2.\">عن المعادن (قارن <r v=\"Job.22.25\"></r>، <r v=\"Ps.12.7\"></r>، <r v=\"Zech.13.9\"></r>)، <b>يُمحَّص (يُصفّى)</b> أو <b>يُنقّى</b> بالنار: <r v=\"Rev.3.18\"></r> (قارن <r v=\"Rev.1.15\"></r>).†</s> </s>","en":"<f><o>πυρόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>πῦρ</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6884\">צרף</h>;]</e> </et> <s><b>to set on fire</b>, <b>burn up</b>. In NT always pass., <s n=\"1.\"><b>to be set on fire</b>, <b>to burn</b>: <r v=\"Eph.6.16\"></r>, <r v=\"2Pet.3.12\"></r>; ptcp., <b>glowing</b>, <r v=\"Rev.1.15\"></r>. Metaph., of grief or indignation, <r v=\"2Cor.11.29\"></r>; of lust, <r v=\"1Cor.7.9\"></r>.</s> <s n=\"2.\">Of metals (cf. <r v=\"Job.22.25\"></r>, <r v=\"Ps.12.7\"></r>, <r v=\"Zech.13.9\"></r>), <b>to be refined</b> or <b>purified</b> by fire: <r v=\"Rev.3.18\"></r> (and so in RV, <r v=\"Rev.1.15\"></r>, but v. supr.).†</s> </s>"},"G4479":{"l":"Ῥεβέκκα","o":1,"ar":"<f><o>Ῥεβέκκα</o>، <g>-ας</g>، <g>ἡ</g>، (العبرية <h n=\"H7259\">רִבְקָה</h>)، </f> <s><b>رفقة</b>: <r v=\"Rom.9.10\"></r>.†</s>","en":"<f><o>Ῥεβέκκα</o>, <g>-ας</g> (v. Bl., § 7, 2), <g>ἡ</g>, (Heb. <h n=\"H7259\">רִבְקָה</h>), </f> <s><b>Rebecca</b>: <r v=\"Rom.9.10\"></r>.†</s>"},"G4432":{"l":"πτωχεία","o":3,"ar":"<f><o>πτωχεία</o>، <g>-ας, ἡ</g></f> <s><b>فقر مُدقِع</b>، <b>عَوَز</b>: <r v=\"2Cor.8.2\"></r>، <r v=\"2Cor.8.9\"></r>، <r v=\"Rev.2.9\"></r>.†</s>","en":"<f><o>πτωχεία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>πτωχεύω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6040\">עֳנִי</h>;]</e> </et> <s><b>beggary</b>, <b>destitution</b>: <r v=\"2Cor.8.2\"></r>, <r v=\"2Cor.8.9\"></r>, <r v=\"Rev.2.9\"></r>.†</s>"},"G4490":{"l":"ῥητῶς","o":1,"ar":"<f>*† <o>ῥητῶς </o></f> ظرف <s><b>بعبارة صريحة، صريحًا</b>: <r v=\"1Tim.4.1\"></r>.†</s>","en":"<f>*† <o>ῥητῶς </o></f> adv. <et> <e t=\"derivation\">(&lt; <g>ῥητός</g>, <i>stated, specified</i>), </e> </et> <s><b>in stated terms, expressly</b>: <r v=\"1Tim.4.1\"></r>.†</s>"},"G4409":{"l":"πρωτεύω","o":1,"ar":"<f><o>πρωτεύω</o></f> <s><b>يكون أولاً</b>، <b>متقدّمًا</b>، <b>له المكانة الأولى</b>: <r v=\"Col.1.18\"></r>.†</s>","en":"<f><o>πρωτεύω</o></f> <et> <e t=\"derivation\">(&lt; <g>πρῶτος</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ezra.5.11\"></r>, <r v=\"2Macc.6.18\"></r> <r v=\"2Macc.13.15\"></r>*;]</e> </et> <s><b>to be first</b>, <b>pre-eminent</b>, <b>have the first place</b>: <r v=\"Col.1.18\"></r>.†</s>"},"G4433":{"l":"πτωχεύω","o":1,"ar":"<f><o>πτωχεύω</o></f> <s n=\"1.\">في اليونانية الكلاسيكية غالبًا: <b>كان شحّاذًا</b>، <b>استعطى</b>.</s> <s n=\"2.\"><b>صار فقيرًا كالمتسوّل</b>، <b>افتقر</b>، <b>كان فقيرًا</b>: عكس <g>πλούσιος ὤν</g>، <r v=\"2Cor.8.9\"></r>.†</s>","en":"<f><o>πτωχεύω</o></f> <et> <e t=\"derivation\">(&lt; <g>πτωχός</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Judg.6.6\"></r>, <r v=\"Ps.79.8\"></r> (<h n=\"H1809\">דּלל</h>); <r v=\"Judg.14.15\"></r> A, <r v=\"Prov.23.21\"></r> (<h n=\"H3423\">ירשׁ</h>); <r v=\"Ps.34.10\"></r> (<h n=\"H7326\">רוּשׁ</h>), <r v=\"Tob.4.21\"></r>*;]</e> </et> <s n=\"1.\"><b>to be a beggar</b>, <b>to beg</b> (so chiefly in cl.).</s> <s n=\"2.\"><b>to be poor as a beggar</b>, <b>to be destitute</b>, <b>poor</b>: opp. to <g>πλούσιος ὤν</g>, <r v=\"2Cor.8.9\"></r>.†</s>"},"G4483":{"l":"λέγω","o":2335,"ar":"<f><o>λέγω</o>،</f> <s> <s n=\"1.\">في اليونانية الكلاسيكية: <b>التقط</b>، <b>جمع</b>، <b>عدّ</b>، <b>سرد</b>.</s> <s n=\"2.\"><b>قال</b>، <b>تكلّم</b>، <b>أكّد</b>، <b>أعلن</b>: مطلقًا، <r v=\"Acts.13.15\"></r> <r v=\"Acts.24.10\"></r>؛ يليه كلام مباشر، <r v=\"Matt.9.34\"></r>، <r v=\"Mark.3.11\"></r>، <r v=\"John.1.29\"></r>، وفي مواضع أخرى؛ يليه <g>ὅτι</g> لنقل القول، <r v=\"Mark.3.21\"></r>، <r v=\"Luke.1.24\"></r>، <r v=\"John.6.14\"></r>، وفي مواضع أخرى؛ مع المنصوب والمصدر، <r v=\"Luke.11.18\"></r>، <r v=\"John.12.29\"></r>، وفي مواضع أخرى؛ بعد فعل قول آخر، <g>προσφωνεῖν κ. λέγειν</g>، <r v=\"Matt.11.17\"></r>، وفي مواضع أخرى؛ <g>ἀπεκρίθη</g> (<g>ἐλάλησεν</g>) <g>λέγων</g> (<g>καὶ λέγει</g>)، <r v=\"Matt.25.9\"></r>، <r v=\"Mark.3.33\"></r>، <r v=\"Mark.7.28\"></r>، <r v=\"Luke.24.6\"></r>، <r v=\"Luke.24.7\"></r>، وفي مواضع أخرى؛ عن الفكر غير المنطوق، <g>λ. ἐν ἑαυτῷ</g>، <r v=\"Matt.3.9\"></r>، <r v=\"Luke.3.8\"></r>، وفي مواضع أخرى؛ عن الكتابة، <r v=\"2Cor.8.8\"></r>، <r v=\"Phil.4.11\"></r>، وفي مواضع أخرى؛ <g>λέγει ἡ γραφή</g>، <r v=\"Rom.4.3\"></r>، <r v=\"Jas.2.23\"></r>، وفي مواضع أخرى؛ مع المنصوب للشيء، <r v=\"Luke.8.8\"></r> <r v=\"Luke.9.33\"></r>، <r v=\"John.5.34\"></r>، وفي مواضع أخرى؛ <g>σὺ λέγεις</g> (عبارة لا تُلزم المتكلم بشيء)، <r v=\"Matt.27.11\"></r>، <r v=\"Mark.15.2\"></r>، <r v=\"Luke.23.3\"></r>، <r v=\"John.18.37\"></r>؛ مع القابل للشخص، يليه كلام مباشر، <r v=\"Matt.8.20\"></r>، <r v=\"Mark.2.17\"></r>، وفي مواضع أخرى كثيرة؛ وكذلك يليه <g>ὅτι</g>، <r v=\"Matt.3.9\"></r>، وفي مواضع أخرى؛ مع حرف جر، <g>πρός</g>، <g>μετά</g>، <g>περί</g>، إلخ، <r v=\"Mark.4.41\"></r>، <r v=\"John.11.56\"></r>، <r v=\"Heb.9.5\"></r>، وفي مواضع أخرى؛ <b>عنى، قصد</b>، <r v=\"Mark.14.71\"></r>، <r v=\"John.6.71\"></r>، <r v=\"1Cor.10.29\"></r>، وفي مواضع أخرى؛ <b>دعا</b>، <b>سمّى</b>، <r v=\"Mark.10.18\"></r>؛ المبني للمجهول، <r v=\"Matt.9.9\"></r>، <r v=\"Mark.15.7\"></r>، وفي مواضع أخرى (قارن <g>ἀντι-</g>، <g>δια-</g> (<g>-μαι</g>)، <g>προ-</g>، <g>συλ-λέγω</g>).</s> </s>","en":"<f><o>λέγω</o>,</f> <et> <e t=\"septuagint\">[in LXX very freq., chiefly for <h n=\"H559\">אמר</h>; <g>λέγει</g> for <h n=\"H5002\">נְאֻם</h>, <r v=\"Gen.22.16\"></r>, al.;]</e> </et> <s> <s n=\"1.\">in Hom., <b>to pick out</b>, <b>gather</b>, <b>reckon</b>, <b>recount</b>.</s> <s n=\"2.\">In Hdt. and Att., <b>to say</b>, <b>speak</b>, <b>affirm</b>, <b>declare</b>: absol., <r v=\"Acts.13.15\"></r> <r v=\"Acts.24.10\"></r>; seq. orat. dir., <r v=\"Matt.9.34\"></r>, <r v=\"Mark.3.11\"></r>, <r v=\"John.1.29\"></r>, al.; seq. <g>ὅτι</g> recit., <r v=\"Mark.3.21\"></r>, <r v=\"Luke.1.24\"></r>, <r v=\"John.6.14\"></r>, al.; acc. et. inf., <r v=\"Luke.11.18\"></r>, <r v=\"John.12.29\"></r>, al.; after another verb of speaking, <g>προσφωνεῖν κ. λέγειν</g>, <r v=\"Matt.11.17\"></r>, al.; <g>ἀπεκρίθη</g> (<g>ἐλάλησεν</g>) <g>λέγων</g> (<g>καὶ λέγει</g>; Dalman, <i>Words</i>, 24 ff.), <r v=\"Matt.25.9\"></r>, <r v=\"Mark.3.33\"></r>, <r v=\"Mark.7.28\"></r>, <r v=\"Luke.24.6\"></r>, <r v=\"Luke.24.7\"></r>, al.; of unspoken thought, <g>λ. ἐν ἑαυτῷ</g>, <r v=\"Matt.3.9\"></r>, <r v=\"Luke.3.8\"></r>, al.; of writing, <r v=\"2Cor.8.8\"></r>, <r v=\"Phil.4.11\"></r>, al.; <g>λέγει ἡ γραφή</g>, <r v=\"Rom.4.3\"></r>, <r v=\"Jas.2.23\"></r>, al.; c. acc. rei, <r v=\"Luke.8.8\"></r> <r v=\"Luke.9.33\"></r>, <r v=\"John.5.34\"></r>, al.; <g>σὺ λέγεις</g> (a non-committal phrase; Swete, <i>Mk.</i>, 359, 369 f.), <r v=\"Matt.27.11\"></r>, <r v=\"Mark.15.2\"></r>, <r v=\"Luke.23.3\"></r>, <r v=\"John.18.37\"></r>; c. dat. pers., seq. orat. dir., <r v=\"Matt.8.20\"></r>, <r v=\"Mark.2.17\"></r>, al. mult.; id. seq. <g>ὅτι</g>, <r v=\"Matt.3.9\"></r>, al.; c. prep., <g>πρός</g>, <g>μετά</g>, <g>περί</g>, etc., <r v=\"Mark.4.41\"></r>, <r v=\"John.11.56\"></r>, <r v=\"Heb.9.5\"></r>, al.; <b>to mean</b> (cl.), <r v=\"Mark.14.71\"></r>, <r v=\"John.6.71\"></r>, <r v=\"1Cor.10.29\"></r>, al.; <b>to call</b>, <b>name</b>, <r v=\"Mark.10.18\"></r>; pass., <r v=\"Matt.9.9\"></r>, <r v=\"Mark.15.7\"></r>, al (cf. <g>ἀντι-</g>, <g>δια-</g> (<g>-μαι</g>), <g>προ-</g>, <g>συλ-λέγω</g>).</s> </s> <sy><i>SYN.</i>: <g>λαλέω</g>, which refers to the utterance, as <g>λέγω</g> to the meaning of what is said, its correspondence with thought (Tr., <i>Syn.</i>, Ixxvi; Thayer, s.v. <g>λαλέω</g>).</sy>"},"G4416":{"l":"πρωτότοκος","o":8,"ar":"<f><o>πρωτότοκος</o>، <g>-ον</g></f> <s><b>بكر</b>: <r v=\"Luke.2.7\"></r>؛ جمع، <r v=\"Heb.11.28\"></r>. مجازيًا، عن أسبقية المسيح (ولعله في الأصل لقب مسياني، قارن <r v=\"Ps.89.28\"></r>، <r v=\"Heb.1.6\"></r>؛ <r v=\"Col.1.15\"></r>): <r v=\"Heb.1.6\"></r>؛ <g>π. πάσης κτίσεως</g>، <r v=\"Col.1.15\"></r>؛ <g>ἐν πολλοῖς ἀδελφοῖς</g>، <r v=\"Rom.8.29\"></r>؛ <g>π.</g> (<g>ἐκ</g>) <g>τ. νεκρῶν</g>، <r v=\"Col.1.18\"></r>، <r v=\"Rev.1.5\"></r>؛ جمع، عن المختارين، <g>ἐκκλησία πρωτοτόκων</g>، <r v=\"Heb.12.23\"></r>.†</s>","en":"<f><o>πρωτότοκος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>πρῶτος</g>, <g>τίκτω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1060\">בְּכוֹר</h>;]</e> </et> <s><b>first-born</b>: <r v=\"Luke.2.7\"></r>; pl., <r v=\"Heb.11.28\"></r>. Metaph., of the priority of Christ (originally perh. a Messianic title, cf. <r v=\"Ps.89.28\"></r>, <r v=\"Heb.1.6\"></r>; v. <i>ICC</i> on <r v=\"Col.1.15\"></r>): <r v=\"Heb.1.6\"></r>; <g>π. πάσης κτίσεως</g>, <r v=\"Col.1.15\"></r>; <g>ἐν πολλοῖς ἀδελφοῖς</g>, <r v=\"Rom.8.29\"></r>; <g>π.</g> (<g>ἐκ</g>) <g>τ. νεκρῶν</g>, <r v=\"Col.1.18\"></r>, <r v=\"Rev.1.5\"></r>; pl., of the elect, <g>ἐκκλησία πρωτοτόκων</g>, <r v=\"Heb.12.23\"></r>.†</s>"},"G4437":{"l":"πυκιός","o":2,"ar":"<f><o>πυκιός</o>، <g>-ή, -όν</g>،</f> <s n=\"1.\"><b>متراصّ</b>، <b>كثيف</b>، <b>صُلب</b>.</s> <s n=\"2.\"><b>متكرّر</b>: <r v=\"1Tim.5.23\"></r>. المحايد الجمع <g>πυκνά</g> ظرفًا: <b>كثيرًا</b>، <b>مرارًا</b>: <r v=\"Mark.7.3\"></r>، <r v=\"Luke.5.33\"></r>. صيغة التفضيل <g>πυκνότερον</g>: <b>كثيرًا جدًّا</b> أو <b>بالأكثر تكرارًا</b>: <r v=\"Acts.24.26\"></r>.†</s>","en":"<f><o>πυκιός</o>, <g>-ή, -όν</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ezek.31.3\"></r> A (<h n=\"H2793\">חֹרֶשׁ</h>), <r v=\"3Macc.1.28\"></r> <r v=\"3Macc.4.10\"></r>, <r v=\"4Macc.12.12\"></r>*;]</e> </et> <s n=\"1.\"><b>close</b>, <b>compact</b>, <b>solid</b>.</s> <s n=\"2.\"><b>frequent</b>: <r v=\"1Tim.5.23\"></r>. Neut. pl., <g>πυκνά</g>, as adv., <b>much</b>, <b>often</b>: <r v=\"Mark.7.3\"></r> T (v.s. <g>πυγμή</g>), <r v=\"Luke.5.33\"></r>. Comparat., <g>πυκνότερον</g>, <b>very often</b> or <b>so much the oftener</b> (v. Bl., § 44, 3<i>n</i>): <r v=\"Acts.24.26\"></r>.†</s>"},"G4421":{"l":"πτηνός","o":1,"ar":"<f>** <o>πτηνός</o>، <g>-ή, -όν</g></f> <s><b>مجنَّح، ذو جناح</b>؛ اسمًا، <g>τὰ π.</g>، <b>الطيور</b>: <r v=\"1Cor.15.39\"></r>.†</s>","en":"<f>** <o>πτηνός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>πέτομαι</g>),</e> <e t=\"septuagint\">[in Aq.: <r v=\"Job.5.7\"></r>*;]</e> </et> <s><b>winged</b>; as subst., <g>τὰ π.</g>, <b>birds</b>: <r v=\"1Cor.15.39\"></r>.†</s>"},"G4426":{"l":"πτύρομαι","o":1,"ar":"<f>* <o>πτύρομαι</o>، فعل لازم الصيغة الوسطى،</f> <s><b>ارتاع</b>، <b>خاف</b>، <b>جَزِع</b>: <r v=\"Phil.1.28\"></r>.†</s>","en":"<f>* <o>πτύρομαι</o>, depon.,</f> <s><b>to be startled</b>, <b>frightened</b>: <r v=\"Phil.1.28\"></r>. (The active <g>πτύρω</g> is also found in some late writers.)†</s>"},"G4464":{"l":"ῥάβδος","o":12,"ar":"<f><o>ῥάβδος</o>، <g>-ου, ἡ </g></f> <s><b>عصا، قضيب</b>: <r v=\"Heb.9.4\"></r>، <r v=\"Rev.11.1\"></r>؛ وعلى وجه الخصوص، </s> <s n=\"(a)\"><b>عصا</b> كالتي تُستعمل في السفر: <r v=\"Matt.10.10\"></r>، <r v=\"Mark.6.8\"></r>، <r v=\"Luke.9.3\"></r>، <r v=\"Heb.11.21\"></r> <i>(السبعينية)</i>؛ </s> <s n=\"(b)\">عصا الحاكم، <b>صولجان</b>: <r v=\"Heb.1.8\"></r> <i>(السبعينية)</i> <r v=\"Rev.2.27\"></r> <r v=\"Rev.12.5\"></r> <r v=\"Rev.19.15\"></r>؛ </s> <s n=\"(c)\"><b>عصا</b> للتأديب (قارن <g>ῥαβδίζω</g>): <g>ἐν ῥ.</g> (انظر تحت مدخل <g>ἐν</g>): <r v=\"1Cor.4.21\"></r>.†</s>","en":"<f><o>ῥάβδος</o>, <g>-ου, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4294\">מַטֶּה</h> (e.g. <r v=\"Gen.47.31\"></r>, MT, <h n=\"H4294\">מַטֶּה</h>, <i>bed</i>), also for <h n=\"H4731\">מַקֵּל</h>, <h n=\"H7626\">שֵׁבֶט</h>, etc. ;]</e> </et> <s><b>a staff, rod</b>: <r v=\"Heb.9.4\"></r>, <r v=\"Rev.11.1\"></r>; in particular, </s> <s n=\"(a)\"><b>a staff</b>, such as is used on a journey: <r v=\"Matt.10.10\"></r>, <r v=\"Mark.6.8\"></r>, <r v=\"Luke.9.3\"></r>, <r v=\"Heb.11.21\"></r> <i>(LXX)</i>; </s> <s n=\"(b)\">a ruler's staff, <b>a sceptre</b>: <r v=\"Heb.1.8\"></r> <i>(LXX)</i> <r v=\"Rev.2.27\"></r> <r v=\"Rev.12.5\"></r> <r v=\"Rev.19.15\"></r>; </s> <s n=\"(c)\"><b>a rod</b> for chastisement (cf. <g>ῥαβδίζω</g>): <g>ἐν ῥ.</g> (v.s. <g>ἐν</g>): <r v=\"1Cor.4.21\"></r>.†</s>"},"G4493":{"l":"ῥιπή","o":1,"ar":"<f>* <o>ῥιπή</o>، <g>ῆς, ἡ</g></f> <s>(في اليونانية الكلاسيكية، شعريًّا: أي حركة سريعة، مثل <b>رمية أو انطلاق</b> الرمح، و<b>اندفاع</b> الريح أو اللهب، و<b>رفرفة</b> الأجنحة، و<b>تلألؤ</b> الأنوار)؛ <g>ῥ. ὀφθαλμοῦ</g>: <b>طرفة</b> عين: <r v=\"1Cor.15.52\"></r>.†</s>","en":"<f>* <o>ῥιπή</o>, <g>ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ῥίπτω</g></x>), </e> </et> <s>poët. in cl., any rapid movement such as the <b>throw or flight</b> of a javelin, the <b>rush</b> of wind or flame, the <b>flapping</b> of wings, the <b>twinkling</b> of lights; <g>ῥ. ὀφθαλμοῦ</g>, the <b>twinkling</b> of an eye: <r v=\"1Cor.15.52\"></r> (L, mg., <g>ῥοπή</g>, q.v.).†</s>"},"G4456":{"l":"πωρόω","o":5,"ar":"<f><o>πωρόω</o>، <g>-ῶ</g></f> <s><b>حجّر</b>، <b>قسّى</b>، <b>كوّن غلظة (جُسْأة)</b>. مجازيًا، <g>π. τ. καρδίαν</g>، <r v=\"John.12.40\"></r>. المبني للمجهول، <r v=\"Rom.11.7\"></r>؛ <g>τ. νοήματα</g>، <r v=\"2Cor.3.14\"></r>؛ <g>ἡ καρδία</g>، <r v=\"Mark.6.52\"></r> <r v=\"Mark.8.17\"></r>.†</s>","en":"<f><o>πωρόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>πῶρος</g>, 1. <i>a stone</i>. 2. <i>a callus</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Job.17.7\"></r> B (<h n=\"H3543\">כּהה</h>), <r v=\"Prov.10.20\"></r> A*;]</e> </et> <s><b>to petrify</b>, <b>harden</b>, <b>form a callus</b>. Metaph., <g>π. τ. καρδίαν</g>, <r v=\"John.12.40\"></r>. Pass., <r v=\"Rom.11.7\"></r>; <g>τ. νοήματα</g>, <r v=\"2Cor.3.14\"></r>; <g>ἡ καρδία</g>, <r v=\"Mark.6.52\"></r> <r v=\"Mark.8.17\"></r>.†</s>"},"G4463":{"l":"ῥαβδίζω","o":2,"ar":"<f><o>ῥαβδίζω</o></f> <s><b>ضرب بالعصي</b>: <r v=\"Acts.16.22\"></r>، <r v=\"2Cor.11.25\"></r>.†</s>","en":"<f><o>ῥαβδίζω</o></f> <et> <e t=\"derivation\">(&lt; <x><g>ῥάβδος</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Judg.6.11\"></r> <r v=\"Ruth.2.17\"></r> (<h n=\"H2251\">חבט</h>) * ;] </e> </et> <s><b>to beat with a rod</b>: <r v=\"Acts.16.22\"></r>, <r v=\"2Cor.11.25\"></r>.†</s>"},"G4434":{"l":"πτωχός","o":34,"ar":"<f><o>πτωχός</o>، <g>-ή, -όν</g></f> <s>عمّن ينحني ويتذلّل، ومن ثمّ: <s n=\"1.\">بمعنى الاسم: <b>شحّاذ، متسوّل</b>: <r v=\"Luke.14.13\"></r>، <r v=\"Luke.14.21\"></r> <r v=\"Luke.16.20\"></r>، <r v=\"Luke.16.22\"></r>.</s> <s n=\"2.\">صفةً: <s n=\"(a)\">أصلاً: <b>حقير، فقير</b> (كالشحّاذ): مجازيًا، <g>στοιχεῖα</g>، <r v=\"Gal.4.9\"></r>؛</s> <s n=\"(b)\">بمعنى أوسع (عكس <g>πλούσιος</g>): <b>فقير، مسكين</b>: <r v=\"Matt.11.5\"></r> <r v=\"Matt.19.21\"></r> <r v=\"Matt.26.9\"></r>، <r v=\"Matt.26.11\"></r>، <r v=\"Mark.10.21\"></r> <r v=\"Mark.12.42\"></r>، <r v=\"Mark.12.43\"></r> <r v=\"Mark.14.5\"></r>، <r v=\"Mark.14.7\"></r>، <r v=\"Luke.4.18\"></r> <r v=\"Luke.7.22\"></r> <r v=\"Luke.18.22\"></r> <r v=\"Luke.19.8\"></r> <r v=\"Luke.21.3\"></r>، <r v=\"John.12.5\"></r>، <r v=\"John.21.6\"></r>، <r v=\"John.12.8\"></r> <r v=\"John.13.29\"></r>، <r v=\"Rom.15.26\"></r>، <r v=\"2Cor.6.10\"></r>، <r v=\"Gal.2.10\"></r>، <r v=\"Jas.2.2\"></r>، <r v=\"Jas.2.3\"></r>، <r v=\"Jas.2.6\"></r>، <r v=\"Rev.13.16\"></r>؛ <g>π. τ. κόσμῳ</g>، <r v=\"Jas.2.5\"></r>؛ مجازيًا، <r v=\"Luke.6.20\"></r>، <r v=\"Rev.3.17\"></r>؛ <g>π. τ. πνεύματι</g>، <r v=\"Matt.5.3\"></r>.†</s> </s> </s>","en":"<f><o>πτωχός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>πτώσσω</g>, <i>to crouch</i>, <i>cower</i>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H6041\">עָנִי</h>, <h n=\"H1800\">דַּל</h>, <h n=\"H7227\">רָשׁ</h>, etc.;]</e> </et> <s>of one who crouches and cowers, hence, <s n=\"1.\">as subst., <b>a beggar</b>: <r v=\"Luke.14.13\"></r>, <r v=\"Luke.14.21\"></r> <r v=\"Luke.16.20\"></r>, <r v=\"Luke.16.22\"></r>.</s> <s n=\"2.\">As adj., <s n=\"(a)\">prop., <b>beggarly</b>: metaph., <g>στοιχεῖα</g>, <r v=\"Gal.4.9\"></r> (v. Lft., in l.);</s> <s n=\"(b)\">in broader sense (opp. to <g>πλούσιος</g>), <b>poor</b>: <r v=\"Matt.11.5\"></r> <r v=\"Matt.19.21\"></r> <r v=\"Matt.26.9\"></r>, <r v=\"Matt.26.11\"></r>, <r v=\"Mark.10.21\"></r> <r v=\"Mark.12.42\"></r>, <r v=\"Mark.12.43\"></r> <r v=\"Mark.14.5\"></r>, <r v=\"Mark.14.7\"></r>, <r v=\"Luke.4.18\"></r> <r v=\"Luke.7.22\"></r> <r v=\"Luke.18.22\"></r> <r v=\"Luke.19.8\"></r> <r v=\"Luke.21.3\"></r>, <r v=\"John.12.5\"></r>, <r v=\"John.21.6\"></r>, <r v=\"John.12.8\"></r> <r v=\"John.13.29\"></r>, <r v=\"Rom.15.26\"></r>, <r v=\"2Cor.6.10\"></r>, <r v=\"Gal.2.10\"></r>, <r v=\"Jas.2.2\"></r>, <r v=\"Jas.2.3\"></r>, <r v=\"Jas.2.6\"></r>, <r v=\"Rev.13.16\"></r>; <g>π. τ. κόσμῳ</g>, <r v=\"Jas.2.5\"></r>; metaph., <r v=\"Luke.6.20\"></r>, <r v=\"Rev.3.17\"></r>; <g>π. τ. πνεύματι</g>, <r v=\"Matt.5.3\"></r>.†</s> </s> </s> <sy><i>SYN.</i>: <g>πένης</g>, q.v.</sy>"},"G4486":{"l":"ῥήγνυμι","o":7,"ar":"<f><o>ῥήγνυμι</o> و(<r v=\"Mark.9.18\"></r>) <g>ῥήσσω</g>، </f> <s n=\"1.\"><b>مزّق، شقّ</b>: <r v=\"Matt.7.6\"></r>، <r v=\"Mark.2.22\"></r>، <r v=\"Luke.5.37\"></r>؛ المبني للمجهول، <r v=\"Matt.9.17\"></r>. </s> <s n=\"2.\">عن الصوت، مع المنصوب، <g>φωνήν</g> إلخ: <b>انفجر بالكلام</b>: مطلقًا، <r v=\"Gal.4.27\"></r> <i>(السبعينية)</i>. </s> <s n=\"3.\">= <g>ῥάσσω</g>: <b>طرح أو صرع أرضًا</b>: <r v=\"Mark.9.18\"></r>، <r v=\"Luke.9.42\"></r> </s> <s>(قارن <g>δια-</g>، <g>περι-</g>، <g>προσ-ρήγνυμι</g>).†</s>","en":"<f><o>ῥήγνυμι</o> and (<r v=\"Mark.9.18\"></r>) <g>ῥήσσω</g>, </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1234\">בּקע</h>, also for <h n=\"H7167\">קרע</h>, etc. ;]</e> </et> <s n=\"1.\"><b>to rend, break asunder</b>: <r v=\"Matt.7.6\"></r>, <r v=\"Mark.2.22\"></r>, <r v=\"Luke.5.37\"></r>; pass., <r v=\"Matt.9.17\"></r>. </s> <s n=\"2.\">Of the voice, c. acc., <g>φωνήν</g>, etc. (Hdt., al.), <b>to break forth into speech</b>: absol., <r v=\"Gal.4.27\"></r> <i>(LXX)</i>. </s> <s n=\"3.\">= <g>ῥάσσω</g> (Dem., al.), <b>to throw or dash down</b>: <r v=\"Mark.9.18\"></r>, <r v=\"Luke.9.42\"></r> </s> <s>(cf. <g>δια-</g>, <g>περι-</g>, <g>προσ-ρήγνυμι</g>).†</s> <sy><i>SYN.</i>: <x><g>θραύω</g></x>, <x><g>κατάγνυμι</g></x> </sy>"},"G4438":{"l":"πυκτεύω","o":1,"ar":"<f>* <o>πυκτεύω</o></f> <s><b>يلاكم</b>: <r v=\"1Cor.9.26\"></r>.†</s>","en":"<f>* <o>πυκτεύω</o></f> <et> <e t=\"derivation\">(&lt; <g>πύκτης</g>, <i>a pugilist</i>),</e> </et> <s><b>to box</b>: <r v=\"1Cor.9.26\"></r>.†</s>"},"G4442":{"l":"πῦρ","o":71,"ar":"<f><o>πῦρ</o>، حالة الجر <g>πυρός, τό</g>،</f> <s><b>نار</b>: <r v=\"Mark.9.22\"></r>، <r v=\"Luke.3.9\"></r>، <r v=\"John.15.6\"></r>، <r v=\"Acts.2.19\"></r>، <r v=\"1Cor.3.13\"></r>، <r v=\"Jas.3.5\"></r>، <r v=\"Rev.8.5\"></r>، وفي مواضع أخرى؛ <g>π. καὶ θεῖον</g>، <r v=\"Luke.17.29\"></r>؛ <g>κατακαίειν</g> (<g>ἐν</g>) <g>π.</g>، <r v=\"Matt.13.40\"></r>، <r v=\"Rev.17.16\"></r> <r v=\"Rev.18.8\"></r>؛ <g>καίεσθαι πυρί</g>، <r v=\"Heb.12.18\"></r>، <r v=\"Rev.8.8\"></r> <r v=\"Rev.21.8\"></r>؛ <g>φλὸξ πυρός</g>، <r v=\"Acts.7.30\"></r>، <r v=\"2Thess.1.8\"></r>، <r v=\"Heb.1.7\"></r>، <r v=\"Rev.1.14\"></r> <r v=\"Rev.2.18\"></r> <r v=\"Rev.19.12\"></r>؛ <g>λαμπάδες πυρός</g>، <r v=\"Rev.4.5\"></r>؛ <g>στῦλοι πυρός</g>، <r v=\"Rev.10.1\"></r>؛ <g>ἄνθρακες πυρός</g>، <r v=\"Rom.12.20\"></r><i>(السبعينية)</i>؛ <g>γλῶσσαι ὡσεὶ πυρός</g>، <r v=\"Acts.2.3\"></r>؛ <g>δοκιμάζειν</g> (<g>πυροῦσθαι</g>) <g>διὰ πυρός</g>، <r v=\"1Pet.1.7\"></r>، <r v=\"Rev.3.18\"></r>؛ <g>ὡς διὰ. π.</g>، <r v=\"1Cor.3.15\"></r>. عن نار جهنم: <r v=\"Mark.9.48\"></r><i>(السبعينية)</i>؛ <g>τὸ π. τὸ αἰώνιον</g>، <r v=\"Matt.18.8\"></r> <r v=\"Matt.25.41\"></r> (قارن <r v=\"4Macc.12.12\"></r>)؛ <g>ἄσβεστον</g>، <r v=\"Mark.9.43\"></r>؛ <g>πυρὸς αἰωνίου δίκην ὑπέχειν</g>، <r v=\"Jude.1.7\"></r>؛ <g>γέεννα τοῦ π.</g>، <r v=\"Matt.5.22\"></r> <r v=\"Matt.18.9\"></r>؛ <g>κάμινος τοῦ π.</g>، <r v=\"Matt.13.42\"></r>، <r v=\"Matt.13.50\"></r>؛ <g>ἡ λίμνη τοῦ π.</g>، <r v=\"Rev.19.20\"></r> <r v=\"Rev.20.10\"></r>، <r v=\"Rev.20.14\"></r>، <r v=\"Rev.20.15\"></r>؛ <g>πυρὶ τηρεῖσθαι</g>، <r v=\"2Pet.3.7\"></r>؛ <g>βασανισθῆναι ἐν π.</g>، <r v=\"Rev.14.10\"></r>. مجازيًا: <g>βαπτίζειν πυρί</g>، <r v=\"Matt.3.11\"></r>، <r v=\"Luke.3.16\"></r>؛ عن اللسان، <r v=\"Jas.3.5\"></r>؛ عن الخصام والشقاق، <r v=\"Luke.12.49\"></r>؛ <g>ἐκ π. ἁρπάζειν</g>، <r v=\"Jude.1.23\"></r>؛ <g>πυρὶ ἁλίζεσθαι</g>، <r v=\"Mark.9.49\"></r>؛ <g>ζῆλος πυρός</g>، <r v=\"Heb.10.27\"></r>؛ عن الله: <g>π. καταναλίσκον</g>، <r v=\"Heb.12.29\"></r><i>(السبعينية)</i>.</s>","en":"<f><o>πῦρ</o>, gen., <g>πυρός, τό</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly and very freq. for <h n=\"H784\">אֵשׁ</h>;]</e> </et> <s><b>fire</b>: <r v=\"Mark.9.22\"></r>, <r v=\"Luke.3.9\"></r>, <r v=\"John.15.6\"></r>, <r v=\"Acts.2.19\"></r>, <r v=\"1Cor.3.13\"></r>, <r v=\"Jas.3.5\"></r>, <r v=\"Rev.8.5\"></r>, al; <g>π. καὶ θεῖον</g>, <r v=\"Luke.17.29\"></r>; <g>κατακαίειν</g> (<g>ἐν</g>) <g>π.</g>, <r v=\"Matt.13.40\"></r>, <r v=\"Rev.17.16\"></r> <r v=\"Rev.18.8\"></r>; <g>καίεσθαι πυρί</g>, <r v=\"Heb.12.18\"></r>, <r v=\"Rev.8.8\"></r> <r v=\"Rev.21.8\"></r>; <g>φλὸξ πυρός</g>, <r v=\"Acts.7.30\"></r>, <r v=\"2Thess.1.8\"></r>, <r v=\"Heb.1.7\"></r>, <r v=\"Rev.1.14\"></r> <r v=\"Rev.2.18\"></r> <r v=\"Rev.19.12\"></r>; <g>λαμπάδες πυρός</g>, <r v=\"Rev.4.5\"></r>; <g>στῦλοι πυρός</g>, <r v=\"Rev.10.1\"></r>; <g>ἄνθρακες πυρός</g>, <r v=\"Rom.12.20\"></r><i>(LXX)</i>; <g>γλῶσσαι ὡσεὶ πυρός</g>, <r v=\"Acts.2.3\"></r>; <g>δοκιμάζειν</g> (<g>πυροῦσθαι</g>) <g>διὰ πυρός</g>, <r v=\"1Pet.1.7\"></r>, <r v=\"Rev.3.18\"></r>; <g>ὡς διὰ. π.</g> (Lft., <i>Notes</i>, 193), <r v=\"1Cor.3.15\"></r>. Of the fire of hell (cf. Dalman, <i>Words</i>,161): <r v=\"Mark.9.48\"></r><i>(LXX)</i>; <g>τὸ π. τὸ αἰώνιον</g>, <r v=\"Matt.18.8\"></r> <r v=\"Matt.25.41\"></r> (cf. <r v=\"4Macc.12.12\"></r>); <g>ἄσβεστον</g>, <r v=\"Mark.9.43\"></r>; <g>πυρὸς αἰωνίου δίκην ὑπέχειν</g>, <r v=\"Jude.1.7\"></r>; <g>γέεννα τοῦ π.</g>, <r v=\"Matt.5.22\"></r> <r v=\"Matt.18.9\"></r>; <g>κάμινος τοῦ π.</g>, <r v=\"Matt.13.42\"></r>, <r v=\"Matt.13.50\"></r>; <g>ἡ λίμνη τοῦ π.</g>, <r v=\"Rev.19.20\"></r> <r v=\"Rev.20.10\"></r>, <r v=\"Rev.20.14\"></r>, <r v=\"Rev.20.15\"></r>; <g>πυρὶ τηρεῖσθαι</g>, <r v=\"2Pet.3.7\"></r>; <g>βασανισθῆναι ἐν π.</g>, <r v=\"Rev.14.10\"></r>. Metaph.: <g>βαπτίζειν πυρί</g>, <r v=\"Matt.3.11\"></r>, <r v=\"Luke.3.16\"></r>; of the tongue, <r v=\"Jas.3.5\"></r>; of strife and discord, <r v=\"Luke.12.49\"></r>; <g>ἐκ π. ἁρπάζειν</g>, <r v=\"Jude.1.23\"></r>; <g>πυρὶ ἁλίζεσθαι</g>, <r v=\"Mark.9.49\"></r>; <g>ζῆλος πυρός</g>, <r v=\"Heb.10.27\"></r>; of God, <g>π. καταναλίσκον</g>, <r v=\"Heb.12.29\"></r><i>(LXX)</i>.</s>"},"G4491":{"l":"ῥίζα","o":17,"ar":"<f><o>ῥίζα</o>، <g>-ης, ἡ </g></f> <s><b>أصل، جذر</b>: <r v=\"Matt.3.10\"></r>، <r v=\"Luke.3.9\"></r>؛ <g>ἐκ ῥιζῶν</g>، <r v=\"Mark.11.20\"></r>؛ <g>ῥ. ἔχειν</g>، <r v=\"Matt.13.6\"></r>، <r v=\"Mark.4.6\"></r>؛ ونفسه يليه <g>ἐν ἑαυτῷ</g>، مجازيًا، <r v=\"Matt.13.21\"></r>، <r v=\"Mark.4.17\"></r>، <r v=\"Luke.8.13\"></r>. مجازيًا، عن السبب والمنشأ والمصدر ونحو ذلك؛ </s> <s n=\"(a)\">عن الأشياء: <g>ῥ. πάντων τ. κακῶν</g>، <r v=\"1Tim.6.10\"></r>؛ </s> <s n=\"(b)\">عن الأشخاص: عن الأسلاف، <r v=\"Rom.11.16-Rom.11.18\"></r>؛ <g>ῥ. πικρίας</g>، <r v=\"Heb.12.15\"></r>. وعمّا ينبت من الأصل: <b>فرع، غصن</b>؛ مجازيًا عن النسل: <r v=\"Rom.15.12\"></r> <i>(السبعينية)</i>، <r v=\"Rev.5.5\"></r> <r v=\"Rev.22.16\"></r>.†</s>","en":"<f><o>ῥίζα</o>, <g>-ης, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8327\">שָׁרַשׁ</h> ;] </e> </et> <s><b>a root</b>: <r v=\"Matt.3.10\"></r>, <r v=\"Luke.3.9\"></r>; <g>ἐκ ῥιζῶν</g>, <r v=\"Mark.11.20\"></r>; <g>ῥ. ἔχειν</g>, <r v=\"Matt.13.6\"></r>, <r v=\"Mark.4.6\"></r>; id. seq. <g>ἐν ἑαυτῷ</g>, fig., <r v=\"Matt.13.21\"></r>, <r v=\"Mark.4.17\"></r>, <r v=\"Luke.8.13\"></r>. Metaph. (as in various senses in cl.), of cause, origin, source, etc.; </s> <s n=\"(a)\">of things, <g>ῥ. πάντων τ. κακῶν</g> (Eur.), <r v=\"1Tim.6.10\"></r>; </s> <s n=\"(b)\">of persons: of ancestors, <r v=\"Rom.11.16-Rom.11.18\"></r>; <g>ῥ. πικρίας</g>, <r v=\"Heb.12.15\"></r>. Of that which springs from a root, <b>a shoot</b>; metaph., of offspring, <r v=\"Rom.15.12\"></r> <i>(LXX)</i>, <r v=\"Rev.5.5\"></r> <r v=\"Rev.22.16\"></r>.†</s>"},"G4417":{"l":"πταίω","o":5,"ar":"<f><o>πταίω</o>،</f> <s n=\"1.\">متعدٍّ: <b>يُعثِر</b> (<r v=\"1Sam.4.3\"></r>).</s> <s n=\"2.\">لازم: <b>يعثر، يزلّ</b>. مجازيًا، بالمعنى الأدبي، <r v=\"Rom.11.11\"></r>، <r v=\"Jas.2.10\"></r> <r v=\"Jas.3.2\"></r>، <r v=\"2Pet.1.10\"></r>.†</s>","en":"<f><o>πταίω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5062\">נגף</h> ni.;]</e> </et> <s n=\"1.\">trans., <b>to cause to stumble</b> (<r v=\"1Sam.4.3\"></r>, cf. Deiss., <i>BS</i>, 68<i>1</i>).</s> <s n=\"2.\">Intrans., <b>to stumble</b>. Metaph., in moral sense, <r v=\"Rom.11.11\"></r>, <r v=\"Jas.2.10\"></r> <r v=\"Jas.3.2\"></r>, <r v=\"2Pet.1.10\"></r>.†</s>"},"G4453":{"l":"πωλέω","o":22,"ar":"<f><o>πωλέω</o>، <g>-ῶ</g>،</f> <s n=\"1.\"><b>بادل</b> أو <b>قايض</b>.</s> <s n=\"2.\"><b>باع</b>: <r v=\"Luke.17.28\"></r>، <r v=\"Rev.13.17\"></r>؛ <g>οἱ πωλοῦντες</g> (الباعة)، <r v=\"Matt.21.12\"></r> <r v=\"Matt.25.9\"></r>، <r v=\"Mark.11.15\"></r>، <r v=\"Luke.19.45\"></r>؛ مع منصوب الشيء، <r v=\"Matt.13.44\"></r> <r v=\"Matt.19.21\"></r> <r v=\"Matt.21.12\"></r>، <r v=\"Mark.10.21\"></r> <r v=\"Mark.11.15\"></r>، <r v=\"Luke.12.33\"></r> <r v=\"Luke.18.22\"></r> <r v=\"Luke.22.36\"></r>، <r v=\"John.2.14\"></r>، <r v=\"John.2.16\"></r>، <r v=\"Acts.5.1\"></r> (أي <g>αὐτά, αὐτόν</g>)، <r v=\"Acts.4.34\"></r>، <r v=\"Acts.4.37\"></r>. المبني للمجهول، <r v=\"1Cor.10.25\"></r>؛ مع المضاف إليه للثمن، <r v=\"Matt.10.29\"></r>، <r v=\"Luke.12.6\"></r>.†</s>","en":"<f><o>πωλέω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4376\">מכר</h>;]</e> </et> <s n=\"1.\"><b>to exchange</b> or <b>barter</b>.</s> <s n=\"2.\"><b>to sell</b>: <r v=\"Luke.17.28\"></r>, <r v=\"Rev.13.17\"></r>; <g>οἱ πωλοῦντες</g>, <r v=\"Matt.21.12\"></r> <r v=\"Matt.25.9\"></r>, <r v=\"Mark.11.15\"></r>, <r v=\"Luke.19.45\"></r>; c. acc. rei, <r v=\"Matt.13.44\"></r> <r v=\"Matt.19.21\"></r> <r v=\"Matt.21.12\"></r>, <r v=\"Mark.10.21\"></r> <r v=\"Mark.11.15\"></r>, <r v=\"Luke.12.33\"></r> <r v=\"Luke.18.22\"></r> <r v=\"Luke.22.36\"></r>, <r v=\"John.2.14\"></r>, <r v=\"John.2.16\"></r>, <r v=\"Acts.5.1\"></r> (sc. <g>αὐτά, αὐτόν</g>), <r v=\"Acts.4.34\"></r>, <r v=\"Acts.4.37\"></r>. Pass., <r v=\"1Cor.10.25\"></r>; c. gen. pretii, <r v=\"Matt.10.29\"></r>, <r v=\"Luke.12.6\"></r>.†</s>"},"G4451":{"l":"πύρωσις","o":3,"ar":"<f><o>πύρωσις</o>، <g>-εως, ἡ</g></f> <s n=\"1.\"><b>احتراق، حريق</b>: <r v=\"Rev.18.9\"></r>، <r v=\"Rev.18.18\"></r>.</s> <s n=\"2.\"><b>تنقية بالنار</b> أو <b>امتحان بالنار</b>: مجازيًا، <r v=\"1Pet.4.12\"></r>.†</s>","en":"<f><o>πύρωσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>πυρόω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.27.21\"></r> (<h n=\"H3564\">כּוּר</h>), <r v=\"Amos.4.9\"></r> (<h n=\"H7711\">שִׁדָּפוֹן</h>)*;]</e> </et> <s n=\"1.\"><b>a burning</b>: <r v=\"Rev.18.9\"></r>, <r v=\"Rev.18.18\"></r>.</s> <s n=\"2.\"><b>a refining</b> or <b>trial by fire</b>: metaph., <r v=\"1Pet.4.12\"></r>.†</s>"},"G4480":{"l":"ῥέδη","o":1,"ar":"<f>*† <o>ῥέδη</o>، <g>-ης, ἡ</g> </f> <s><b>مركبة</b>: <r v=\"Rev.18.13\"></r>.†</s>","en":"<f>*† <o>ῥέδη</o> (v. WH, <i>App.</i>, 151), <g>-ης, ἡ</g> </f> <et> <e t=\"derivation\">(a Gallic word), </e> </et> <s><b>a chariot</b>: <r v=\"Rev.18.13\"></r>.†</s>"},"G4406":{"l":"πρώϊμος","o":1,"ar":"<f><o>πρώϊμος</o>، انظر تحت مدخل <g>πρόϊμος</g>.</f>","en":"<f><o>πρώϊμος</o>, v.s. <g>πρόϊμος</g>.</f>"},"G4423":{"l":"πτόησις","o":1,"ar":"<f><o>πτόησις</o>، <g>-εως, ἡ</g></f> <s><b>اضطراب</b>، <b>هياج</b> ناتج عن أي انفعال، لكن خاصةً عن الخوف، ومن ثَمّ <b>رُعب</b>: <g>φοβεῖσθαι πτόησιν</g>، <b>خاف خوفًا</b> (مفعول مطلق) أو <b>خاف من أي رُعب</b>: <r v=\"1Pet.3.6\"></r>.†</s>","en":"<f><o>πτόησις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>πτοέω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.3.25\"></r> (<h n=\"H6343\">פַּחַד</h>), Sir 50:4 <h>א</h><i>1</i>, <r v=\"1Macc.3.25\"></r> R*;]</e> </et> <s><b>a fluttering</b>, <b>excitement</b>, caused by any emotion, but esp. by fear, hence, <b>terror</b>: <g>φοβεῖσθαι πτόησιν</g>, <b>to be afraid with</b> (cogn. acc.) or <b>of any terror</b> (v. <i>ICC</i>, in l.): <r v=\"1Pet.3.6\"></r>.†</s>"},"G4473":{"l":"ῥαντισμός","o":2,"ar":"<f>† <o>ῥαντισμός</o>، <g>-ῦο, ὁ</g></f> <s><b>رشّ</b>: عن رشّ الدم الطقسي للتطهير، <r v=\"Heb.12.24\"></r>، <r v=\"1Pet.1.2\"></r>.†</s>","en":"<f>† <o>ῥαντισμός</o>, <g>-ῦο, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ῥαντίζω</g></x>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H5079\">נִדָּה</h> ;] </e> </et> <s><b>sprinkling</b>: of the ceremonial sprinkling of blood for purification, <r v=\"Heb.12.24\"></r>, <r v=\"1Pet.1.2\"></r> (v. Hort, <i>Pe.</i>, 23 ff.).†</s>"},"G4439":{"l":"πύλη","o":11,"ar":"<f><o>πύλη</o>، <g>-ης, ἡ</g>،</f> <s><b>باب</b>: <r v=\"Luke.7.12\"></r>، <r v=\"Acts.9.24\"></r> <r v=\"Acts.12.10\"></r> <r v=\"Acts.16.13\"></r>، <r v=\"Heb.13.12\"></r>؛ <g>ἡ Ὡραία Π. τ. ἱεροῦ</g>، <r v=\"Acts.3.10\"></r>. مجازيًا، <r v=\"Matt.7.13\"></r>، <r v=\"Matt.7.14\"></r>؛ <g>πύλαι ᾅδου</g> (<r v=\"Wis.16.13\"></r>، <r v=\"3Macc.5.51\"></r>، وقارن <g>κλεῖς ᾅδου</g>، <r v=\"Rev.1.18\"></r>): <r v=\"Matt.16.18\"></r>.†</s>","en":"<f><o>πύλη</o>, <g>-ης, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly and very freq. for <h n=\"H8179\">שַׁעַר</h> sometimes for <h n=\"H1817\">דֶּלֶת</h>, <h n=\"H6607\">פֶּתַח</h>;]</e> </et> <s><b>a gate</b>: <r v=\"Luke.7.12\"></r>, <r v=\"Acts.9.24\"></r> <r v=\"Acts.12.10\"></r> <r v=\"Acts.16.13\"></r>, <r v=\"Heb.13.12\"></r>; <g>ἡ Ὡραία Π. τ. ἱεροῦ</g>, <r v=\"Acts.3.10\"></r>. Metaph., <r v=\"Matt.7.13\"></r>, <r v=\"Matt.7.14\"></r>; <g>πύλαι ᾅδου</g> (<r v=\"Wis.16.13\"></r>, <r v=\"3Macc.5.51\"></r>, and cf. <g>κλεῖς ᾅδου</g>, <r v=\"Rev.1.18\"></r>): <r v=\"Matt.16.18\"></r>.†</s>"},"G4494":{"l":"ῥιπίζω","o":1,"ar":"<f><o>ῥιπίζω</o></f> <s>أصلاً، <b>أذكى النار بالتهوية</b>، ومن ثم عمومًا عند الكتّاب المتأخرين، <b>أثار نسيمًا</b>. وفي المبني للمجهول، <b>تخبطه الريح أو تدفعه</b>: عن الأمواج، <g>ἀνεμιζομένῳ καὶ ῥιπιζομένῳ</g>، <b>تدفعه الريح وتهيجه</b>، <r v=\"Jas.1.6\"></r>.†</s>","en":"<f><o>ῥιπίζω</o></f> <et> <e t=\"derivation\">(&lt; <g>ῥιπίς</g>, <i>a fan</i>) </e> <e t=\"septuagint\">[in LXX: <r v=\"Dan.2.35\"></r> (<h n=\"H5376\">נְשָׂא</h>) * ;] </e> </et> <s>primarily, <b>to fan</b> a fire, hence generally, <b>to make a breeze</b> (Plut., al.). In pass. (cf. Philo, <l>de incer. mund.</l>, 24), <b>to be tossed or blown by the wind</b>: of waves, <g>ἀνεμιζομένῳ καὶ ῥιπιζομένῳ</g>, <b>blown and raised with the wind</b> (Hort, in l.), <r v=\"Jas.1.6\"></r>.†</s>"},"G4455":{"l":"πώποτε","o":6,"ar":"<f><o>πώ-ποτε</o>،</f> ظرف، <s><b>قطّ (حتى الآن)</b>: <r v=\"Luke.19.30\"></r>، <r v=\"John.1.18\"></r> <r v=\"John.5.37\"></r> <r v=\"John.6.35\"></r> <r v=\"John.8.33\"></r>، <r v=\"1John.4.12\"></r>.†</s>","en":"<f><o>πώ-ποτε</o>,</f> adv., <s><b>ever yet</b>: <r v=\"Luke.19.30\"></r>, <r v=\"John.1.18\"></r> <r v=\"John.5.37\"></r> <r v=\"John.6.35\"></r> <r v=\"John.8.33\"></r>, <r v=\"1John.4.12\"></r>.†</s>"},"G4407":{"l":"πρωινός","o":2,"ar":"<f>† <o>πρωινός</o></f> <s><b>عند الصباح الباكر</b>، <b>صُبحي</b>: <g>ἀστήρ</g>، <r v=\"Rev.2.28\"></r> <r v=\"Rev.22.16\"></r>.†</s>","en":"<f>† <o>πρωινός</o></f> <et> <e t=\"derivation\">(Rec. <g>-ϊνος</g>, v. WH, <i>App.</i>, <g>ή, -όν</g> (&lt; <g>πρωί</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1242\">בֹּקֶר</h>;]</e> <e t=\"derivation\">= cl. <g>πρώιος</g>,</e> </et> <s><b>at early morn</b>, <b>early</b>: <g>ἀστήρ</g>, <r v=\"Rev.2.28\"></r> <r v=\"Rev.22.16\"></r>.†</s>"},"G4447":{"l":"πύρινος","o":1,"ar":"<f><o>πύρινος</o>، <g>-η, -ον</g>،</f> <s><b>ناري</b>: <r v=\"Rev.9.17\"></r>.†</s>","en":"<f><o>πύρινος</o>, <g>-η, -ον</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ezek.28.14\"></r>, <r v=\"Ezek.28.16\"></r> (<h n=\"H784\">אֵשׁ</h>), <r v=\"Sir.48.9\"></r>*;]</e> </et> <s><b>fiery</b>: <r v=\"Rev.9.17\"></r>.†</s>"},"G4472":{"l":"ῥαντίζω","o":4,"ar":"<f>† <o>ῥαντίζω </o></f> <s>= الكلاسيكية <g>ῥαίνω</g>، </s> <s><b>رشّ، نضح</b>: مع المنصوب، <r v=\"Heb.9.13\"></r>، <r v=\"Heb.9.19\"></r>؛ ونفسه مع القابل، <r v=\"Heb.9.21\"></r>؛ المبني للمجهول، <r v=\"Rev.19.13\"></r>؛ عن التطهير بالرشّ، <r v=\"Heb.10.22\"></r>؛ الصيغة الوسطى، <r v=\"Mark.7.4\"></r>.†</s> <s><g>περι-ραίνω</g> </s> <s>رشّ حول: <r v=\"Rev.19.13\"></r>.†</s>","en":"<f>† <o>ῥαντίζω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Lev.6.27\"></r> (20), <r v=\"2Kgs.9.33\"></r> (<h n=\"H5137\">נזה</h>), <r v=\"Ps.51.7\"></r> (<h n=\"H2398\">חטא</h> pi.) * ;] </e> </et> <s>= cl., <g>ῥαίνω</g>, </s> <s><b>to sprinkle, besprinkle</b>: c. acc., <r v=\"Heb.9.13\"></r>, <r v=\"Heb.9.19\"></r>; id. et dat., <r v=\"Heb.9.21\"></r>; pass., <r v=\"Rev.19.13\"></r>, WH; of cleansing by sprinkling, <r v=\"Heb.10.22\"></r> (v. M, <i>Gr.</i>, ii, 100); mid., <r v=\"Mark.7.4\"></r> (WH, txt., R, mg.).†</s> <s><g>περι-ραίνω</g> </s> <et> <e t=\"derivation\">(<g>-ρραίνω</g>, Rec., v. WH, <i>App.</i>, 139 f.), </e> <e t=\"septuagint\">[in LXX for <h n=\"H5137\">נָזָה</h> hi. ;] </e> </et> <s>to sprinkle around: <r v=\"Rev.19.13\"></r> T (<g>ῤεραντισμένον</g>, WH; <g>ῤε-</g>, R, txt.; <g>βεβαμμένον</g>, Rec., R, mg.).†</s>"},"G4440":{"l":"πυλών","o":18,"ar":"<f><o>πυλών</o>، <g>-ῶνος, ὁ</g></f> <s n=\"1.\"><b>رواق</b> أو <b>دهليز</b> البيت أو القصر: <r v=\"Matt.26.71\"></r>، <r v=\"Luke.16.20\"></r>، <r v=\"Acts.10.17\"></r>، <r v=\"Acts.12.13\"></r>، <r v=\"Acts.12.14\"></r>.</s> <s n=\"2.\"><b>مدخل البوابة</b> أو <b>برج البوابة</b> في مدينة مسوَّرة: <r v=\"Acts.14.13\"></r>، <r v=\"Rev.21.12\"></r>، <r v=\"Rev.21.13\"></r>، <r v=\"Rev.21.15\"></r>، <r v=\"Rev.21.21\"></r>، <r v=\"Rev.21.25\"></r>، <r v=\"Rev.22.14\"></r>.†</s>","en":"<f><o>πυλών</o>, <g>-ῶνος, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>πύλη</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6607\">פֶּתַח</h>, <h n=\"H8179\">שַׁעַר</h>;]</e> </et> <s n=\"1.\">the <b>porch</b> or <b>vestibule</b> of a house or palace: <r v=\"Matt.26.71\"></r>, <r v=\"Luke.16.20\"></r>, <r v=\"Acts.10.17\"></r> <r v=\"Acts.12.13\"></r>, <r v=\"Acts.12.14\"></r>.</s> <s n=\"2.\">The <b>gate-way</b> or <b>gate-tower</b> of a walled town: <r v=\"Acts.14.13\"></r>, <r v=\"Rev.21.12\"></r>, <r v=\"Rev.21.13\"></r>, <r v=\"Rev.21.15\"></r>, <r v=\"Rev.21.21\"></r>, <r v=\"Rev.21.25\"></r> <r v=\"Rev.22.14\"></r>.†</s>"},"G4420":{"l":"πτέρυξ","o":5,"ar":"<f><o>πτέρυξ</o>، <g>-υγος, ἡ</g></f> <s><b>جناح</b>: للطيور، <r v=\"Matt.23.37\"></r>، <r v=\"Luke.13.34\"></r>، <r v=\"Rev.12.14\"></r>؛ للمخلوقات التي تُرى في رؤيا، <r v=\"Rev.4.8\"></r>، <r v=\"Rev.9.9\"></r>.†</s>","en":"<f><o>πτέρυξ</o>, <g>-υγος, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>πέτομαι</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3671\">כָּנָף</h>;]</e> </et> <s><b>a wing</b>: of birds, <r v=\"Matt.23.37\"></r>, <r v=\"Luke.13.34\"></r>, <r v=\"Rev.12.14\"></r>; of creatures seen in a vision, <r v=\"Rev.4.8\"></r> <r v=\"Rev.9.9\"></r>.†</s>"},"G4460":{"l":"Ῥαάβ","o":2,"ar":"<f><o>Ῥαάβ</o> (و<g>Ραχάβ</g>، <r v=\"Matt.1.5\"></r>)، <g>ἡ</g>، لا يُصرَّف</f> <s><b>راحاب</b> (السبعينية، <r v=\"Josh.2.1\"></r>، وفي مواضع أخرى): <r v=\"Heb.11.31\"></r>، <r v=\"Jas.2.25\"></r>.†</s>","en":"<f><o>Ῥαάβ</o> (and <g>Ραχάβ</g>, <r v=\"Matt.1.5\"></r>; <g>Ραχάβη, -ης</g>, in FlJ), <g>ἡ</g>, indecl.</f> <et> <e t=\"derivation\">(Heb. <h n=\"H7342\">רָחָב</h>),</e> </et> <s><b>Rahab</b> (LXX, <r v=\"Josh.2.1\"></r>, al.): <r v=\"Heb.11.31\"></r>, <r v=\"Jas.2.25\"></r>.†</s>"},"G4415":{"l":"πρωτοτόκια","o":1,"ar":"<f>† <o>πρωτοτόκια</o>، <g>-ων, τά</g></f> <s><b>حقوق البكر</b>، <b>البكورية</b>: <r v=\"Heb.12.16\"></r>.†</s>","en":"<f>† <o>πρωτοτόκια</o>, <g>-ων, τά</g></f> <et> <e t=\"derivation\">(&lt; <g>πρωτότοκος</g>),</e> <e t=\"septuagint\">[in LXX (with v.l. <g>-εῖα, -εία</g>): <r v=\"Gen.25.31\"></r> ff. <r v=\"Gen.27.36\"></r>, <r v=\"Deut.21.17\"></r>, <r v=\"1Chr.5.1\"></r> (<h n=\"H1062\">בְּכוֹרָה</h>)*;]</e> </et> <s><b>the rights of the first-born</b>, <b>birthright</b> (= cl. <g>ἡ πρεσβεία</g>): <r v=\"Heb.12.16\"></r>.†</s>"},"G4430":{"l":"πτῶμα","o":7,"ar":"<f><o>πτῶμα</o>، <g>-τος, τό</g></f> <s n=\"1.\">في اليونانية الكلاسيكية والسبعينية: <b>سقطة</b>، ومجازيًا: <b>نكبة</b>، <b>بليّة</b>.</s> <s n=\"2.\">ما قد سقط؛ <s n=\"(a)\">عند الكتّاب المتأخرين: عن المباني، <b>خراب، أنقاض</b>؛</s> <s n=\"(b)\">عن الكائنات الحية (في الكلاسيكية مع المضاف إليه عادةً، <g>νεκρῶν</g>، إلخ)، ويأتي أيضًا مطلقًا، كما عند الكتّاب المتأخرين وفي العهد الجديد: <b>جسد ساقط</b>، <b>جيفة</b>، <b>جثة</b>: <r v=\"Matt.14.12\"></r> <r v=\"Matt.24.28\"></r>، <r v=\"Mark.15.45\"></r>؛ <g>π. αὐτοῦ</g>، <r v=\"Mark.6.29\"></r>؛ <g>αὐτῶν</g>، <r v=\"Rev.11.8\"></r>، <r v=\"Rev.11.9\"></r>.†</s> </s>","en":"<f><o>πτῶμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>πίπτω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Judg.14.8\"></r> (<h n=\"H4658\">מַפֶּלֶת</h>), <r v=\"Job.16.15\"></r> (<r v=\"Job.16.14\"></r>) (<h n=\"H6556\">פֶּרֶץ</h>), <r v=\"Isa.51.19\"></r> (<h n=\"H7701\">שֹׁד</h>), <r v=\"Jdt.8.19\"></r>, <r v=\"Wis.4.18\"></r>, al.;]</e> </et> <s n=\"1.\"><b>a fall</b>, metaph., <b>a misfortune</b>, <b>calamity</b> (Trag., Plat., Polyb., al.; LXX).</s> <s n=\"2.\">That which has fallen; <s n=\"(a)\">of buildings, <b>a ruin</b> (Polyb.);</s> <s n=\"(b)\">of living creatures, in cl. (poët. only) usually c. gen., <g>νεκρῶν</g>, etc., but also absol., as in late writers and NT, <b>a fallen body</b>, <b>a carcase</b>, <b>corpse</b>: <r v=\"Matt.14.12\"></r> <r v=\"Matt.24.28\"></r>, <r v=\"Mark.15.45\"></r>; <g>π. αὐτοῦ</g>, <r v=\"Mark.6.29\"></r>; <g>αὐτῶν</g>, <r v=\"Rev.11.8\"></r>, <r v=\"Rev.11.9\"></r> (cf. Rutherford, <i>NPhr.</i>, 472 f.).†</s> </s>"},"G4450":{"l":"πυρρός","o":2,"ar":"<f><o>πυρρός</o>، <g>-ά, -όν</g></f> <s><b>أحمر ناري</b>: <r v=\"Rev.6.4\"></r> <r v=\"Rev.12.3\"></r>.†</s>","en":"<f><o>πυρρός</o>, <g>-ά, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>πῦρ</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H123\">אֱדֹם</h>;]</e> </et> <s><b>fiery red</b>: <r v=\"Rev.6.4\"></r> <r v=\"Rev.12.3\"></r>.†</s>"},"G4444":{"l":"πύργος","o":4,"ar":"<f><o>πύργος</o>، <g>-ου, ὁ</g>،</f> <s><b>برج</b>: <r v=\"Luke.13.4\"></r>؛ عن برج الحراسة في الكرم (<r v=\"Isa.5.2\"></r>): <r v=\"Matt.21.33\"></r>، <r v=\"Mark.12.1\"></r>، وعلى الأرجح <r v=\"Luke.14.28\"></r>.†</s>","en":"<f><o>πύργος</o>, <g>-ου, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4026\">מִגְדָּל</h>;]</e> </et> <s><b>a tower</b>: <r v=\"Luke.13.4\"></r>; of a watch-tower in a vineyard (<r v=\"Isa.5.2\"></r>): <r v=\"Matt.21.33\"></r>, <r v=\"Mark.12.1\"></r>, and prob., <r v=\"Luke.14.28\"></r>.†</s>"},"G4410":{"l":"πρωτοκαθεδρία","o":4,"ar":"<f>*† <o>πρωτοκαθεδρία</o>، <g>-ας, ἡ</g></f> <s><b>المتكأ الأول، صدر المجلس</b>: <r v=\"Matt.23.6\"></r>، <r v=\"Mark.12.39\"></r>، <r v=\"Luke.11.43\"></r>، <r v=\"Luke.20.46\"></r>.†</s>","en":"<f>*† <o>πρωτοκαθεδρία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>πρῶιος</g>, <g>καθέδρα</g>),</e> </et> <s><b>the chief seat</b>: <r v=\"Matt.23.6\"></r>, <r v=\"Mark.12.39\"></r> (v. Swete, in l.), <r v=\"Luke.11.43\"></r> <r v=\"Luke.20.46\"></r>.†</s>"},"G4470":{"l":"ῥάκος","o":2,"ar":"<f><o>ῥάκος</o>، <g>-ους, τό </g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>ثوب ممزَّق</b>. </s> <s n=\"2.\"><b>خِرقة، رقعة، قطعة</b> من قماش: <r v=\"Matt.9.16\"></r>، <r v=\"Mark.2.21\"></r>.†</s>","en":"<f><o>ῥάκος</o>, <g>-ους, τό </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Isa.64.6\"></r> (5) (<h n=\"H899\">בֶּגֶד</h>), <r v=\"Jer.38.11\"></r> (<h n=\"H5499\">סְחָבָה</h>), <r v=\"Ezra.4.17\"></r> * ;] </e> </et> <s n=\"1.\"><b>a ragged garment</b> (Hom.). </s> <s n=\"2.\"><b>a rag, remnant, piece</b> of cloth: <r v=\"Matt.9.16\"></r>, <r v=\"Mark.2.21\"></r>.†</s>"},"G4431":{"l":"πτῶσις","o":2,"ar":"<f><o>πτῶσις</o>، <g>-εως, ἡ</g></f> <s><b>سقوط</b>، <b>سقطة</b>: <r v=\"Matt.7.27\"></r>؛ مجازيًا، <r v=\"Luke.2.34\"></r>.†</s>","en":"<f><o>πτῶσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>πίπτω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5063\">נֶגֶף</h>, <h n=\"H4658\">מַפֶּלֶת</h>, and cogn. forms;]</e> </et> <s><b>a falling</b>, <b>fall</b> (Plat., Plut., al.): <r v=\"Matt.7.27\"></r>; metaph., <r v=\"Luke.2.34\"></r>.†</s>"},"G4429":{"l":"πτύω","o":3,"ar":"<f><o>πτύω</o>،</f> <s><b>تفل، بصق</b>: <r v=\"Mark.7.33\"></r>، <r v=\"Mark.8.23\"></r>، <r v=\"John.9.6\"></r> (قارن <g>ἐκ-</g>، <g>ἐμ-πτύω</g>).†</s>","en":"<f><o>πτύω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Num.12.14\"></r> (<h n=\"H3417\">ירק</h>), <r v=\"Sir.28.12\"></r>*;]</e> </et> <s><b>to spit</b>: <r v=\"Mark.7.33\"></r> <r v=\"Mark.8.23\"></r>, <r v=\"John.9.6\"></r> (cf. <g>ἐκ-</g>, <g>ἐμ-πτύω</g>).†</s>"},"G4428":{"l":"πτύσσω","o":1,"ar":"<f>* <o>πτύσσω</o>،</f> <s><b>طوى</b>؛ عن الدَّرج، <b>لفَّ</b>: <g>βιβλίον</g>، <r v=\"Luke.4.20\"></r> (قارن <g>ἀνα-πτύσσω</g>).†</s>","en":"<f>* <o>πτύσσω</o>,</f> <s><b>to fold</b>; of a scroll, <b>to roll up</b>: <g>βιβλίον</g>, <r v=\"Luke.4.20\"></r> (cf. <g>ἀνα-πτύσσω</g>).†</s>"},"G4476":{"l":"ῥαφίς","o":2,"ar":"<f>* <o>ῥαφίς</o>، <g>-ίδος, ἡ</g></f> <s><b>إبرة</b>: <r v=\"Matt.19.24\"></r>، <r v=\"Mark.10.25\"></r> (قارن <g>βελόνη</g>).†</s>","en":"<f>* <o>ῥαφίς</o>, <g>-ίδος, ἡ</g></f> <et> <e t=\"derivation\">(<g>ῥάπτω</g>, <i>to sew</i>), </e> </et> <s><b>a needle</b>: <r v=\"Matt.19.24\"></r>, <r v=\"Mark.10.25\"></r> (cf. <g>βελόνη</g>).†</s>"},"G4489":{"l":"ῥήτωρ","o":1,"ar":"<f>* <o>ῥήτωρ</o>، <g>-ορος, ὁ </g></f> <s><b>خطيب عام، خطيب</b>: <r v=\"Acts.24.1\"></r>.†</s>","en":"<f>* <o>ῥήτωρ</o>, <g>-ορος, ὁ </g></f> <s><b>a public speaker, an orator</b>: <r v=\"Acts.24.1\"></r>.†</s>"},"G4465":{"l":"ῥαβδοῦχος","o":2,"ar":"<f>* <o>ῥαβδοῦχος</o>، <g>-ου, ό</g></f> <s>حامل العصا أو صولجان الوظيفة؛ </s> <s n=\"(a)\">في اليونانية الكلاسيكية: <b>حَكَم أو قاضٍ</b>؛ </s> <s n=\"(b)\">عند الكتّاب المتأخرين: <b>جلّاد</b>، أي حامل العصيّ الروماني: <r v=\"Acts.16.35\"></r>، <r v=\"Acts.16.38\"></r>.†</s>","en":"<f>* <o>ῥαβδοῦχος</o>, <g>-ου, ό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ῥάβδος</g></x>, <x><g>ἔχω</g></x>), </e> </et> <s>one who carries a rod or staff of office; </s> <s n=\"(a)\">an <b>umpire or judge</b> (Plat.); </s> <s n=\"(b)\">in late writers, a Roman <b>lictor</b>: <r v=\"Acts.16.35\"></r>, <r v=\"Acts.16.38\"></r>.†</s>"},"G4481":{"l":"Ῥεμφάν","o":1,"ar":"<f><o>Ῥεμφάν</o>، <g>Ῥεφάς</g>، انظر تحت مدخل <g>Ῥομφά</g>.</f>","en":"<f><o>Ῥεμφάν</o>, <g>Ῥεφάς</g>, v.s. <g>Ῥομφά</g>.</f>"},"G4441":{"l":"πυνθάνομαι","o":12,"ar":"<f><o>πυνθάνομαι</o>،</f> <s n=\"1.\"><b>يستخبر، يستعلم</b>: مع المنصوب للشيء، <r v=\"John.4.42\"></r>، <r v=\"Acts.23.20\"></r>؛ يليه سؤال غير مباشر، <r v=\"Matt.2.4\"></r>، <r v=\"Luke.15.26\"></r> <r v=\"Luke.18.36\"></r>، <r v=\"Acts.10.18\"></r> <r v=\"Acts.21.33\"></r>؛ سؤال مباشر، <r v=\"Acts.4.7\"></r> <r v=\"Acts.10.29\"></r> <r v=\"Acts.23.19\"></r>؛ يليه <g>παρά</g> مع المضاف إليه للشخص، <r v=\"Matt.2.4\"></r>، <r v=\"John.4.52\"></r>.</s> <s n=\"2.\"><b>يعلم</b> بالاستخبار: يليه <g>ὅτι</g>، <r v=\"Acts.23.34\"></r>.†</s>","en":"<f><o>πυνθάνομαι</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H1875\">דּרשׁ</h>;]</e> </et> <s n=\"1.\"><b>to inquire</b>: c. acc. rei, <r v=\"John.4.42\"></r>, <r v=\"Acts.23.20\"></r>; seq. quæst. indir., <r v=\"Matt.2.4\"></r>, <r v=\"Luke.15.26\"></r> <r v=\"Luke.18.36\"></r>, <r v=\"Acts.10.18\"></r> <r v=\"Acts.21.33\"></r>; quæst. dir., <r v=\"Acts.4.7\"></r> <r v=\"Acts.10.29\"></r> <r v=\"Acts.23.19\"></r>; seq. <g>παρά</g>, c. gen. pers., <r v=\"Matt.2.4\"></r>, <r v=\"John.4.52\"></r>.</s> <s n=\"2.\"><b>to learn</b> by inquiry: seq. <g>ὅτι</g>, <r v=\"Acts.23.34\"></r>.†</s>"},"G4404":{"l":"πρωί","o":12,"ar":"<f><o>πρωί</o>،</f> ظرف <s><b>صباحًا</b>، <b>باكرًا</b>: <r v=\"Matt.16.3\"></r> <r v=\"Matt.21.18\"></r>، <r v=\"Mark.1.35\"></r> <r v=\"Mark.11.20\"></r> <r v=\"Mark.13.35\"></r> <r v=\"Mark.15.1\"></r> <r v=\"Mark.16.9\"></r>، <r v=\"John.18.28\"></r> <r v=\"John.20.1\"></r>؛ <g>λίαν π.</g>، <r v=\"Mark.16.2\"></r>؛ <g>ἅμα π.</g>، <r v=\"Matt.20.1\"></r>؛ <g>ἀπὸ π.</g> (قارن <g>ἀπὸ πρωΐθεν</g>، <r v=\"Exod.18.13\"></r>)، <r v=\"Acts.28.23\"></r>.†</s>","en":"<f><o>πρωί</o> (Rec. <g>πρωΐ</g>),</f> adv. <et> <e t=\"derivation\">(&lt; <g>πρό</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1242\">בֹּקֶר</h>, <h n=\"H1242\">בַּבֹּקֶר</h>;]</e> </et> <s><b>in the morning</b>, <b>early</b>: <r v=\"Matt.16.3\"></r> (R, txt.) <r v=\"Matt.21.18\"></r>, <r v=\"Mark.1.35\"></r> <r v=\"Mark.11.20\"></r> <r v=\"Mark.13.35\"></r> <r v=\"Mark.15.1\"></r> <r v=\"Mark.16.9\"></r>, <r v=\"John.18.28\"></r> <r v=\"John.20.1\"></r>; <g>λίαν π.</g>, <r v=\"Mark.16.2\"></r>; <g>ἅμα π.</g>, <r v=\"Matt.20.1\"></r>; <g>ἀπὸ π.</g> (cf. <g>ἀπὸ πρωΐθεν</g>, <r v=\"Exod.18.13\"></r>), <r v=\"Acts.28.23\"></r>.†</s>"},"G4469":{"l":"ῥακά","o":1,"ar":"<f>* <o>ῥακά</o>، </f> <s>يُفهم عادةً على أنه يمثّل الآرامية <h n=\"????\">רֵיקָא</h>، وهي صيغة مختصرة من <h n=\"H7386\">רֵיקָן</h>، «فارغ»، كما تُنطق في اللهجة الجليلية؛ تعبير احتقار، <b>رَقا</b>: <r v=\"Matt.5.22\"></r>.†</s>","en":"<f>* <o>ῥακά</o> (T, <g>ῥαχά</g>), </f> <s>usually taken to represent the Aram. <h n=\"????\">רֵיקָא</h>, a shortened form of <h n=\"H7386\">רֵיקָן</h>, \"empty,\" as vocalized in the Galilæan dialect; an expression of contempt, <b>raca</b>: <r v=\"Matt.5.22\"></r> (cf. <i>DB</i>, iv, 191 f.; and for other explanations, v. Zorell, s.v.).†</s>"},"G4474":{"l":"ῥαπίζω","o":2,"ar":"<f><o>ῥαπίζω</o></f> <s n=\"1.\">بالمعنى الحرفي، <b>يضرب بالعصا</b>. </s> <s n=\"2.\">عند الكتّاب المتأخرين، <b>يلطم (الوجه) بكفّ اليد</b>: <r v=\"Matt.26.67\"></r>؛ مع المنصوب للشخص، يليه <g>εἰς τ. σιαγόνα</g>، <r v=\"Matt.5.39\"></r>.†</s>","en":"<f><o>ῥαπίζω</o></f> <et> <e t=\"derivation\">(&lt; <g>ῥαπίς</g>, <i>a rod</i>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Judg.16.25\"></r>, <r v=\"Hos.11.4\"></r>, <r v=\"1Esd.4.31\"></r> * ;] </e> </et> <s n=\"1.\">prop., <b>to strike with a rod</b>. </s> <s n=\"2.\">In late writers, <b>to strike (the face) with the palm of the hand</b>: <r v=\"Matt.26.67\"></r>; c. acc. pers., seq. <g>εἰς τ. σιαγόνα</g>, <r v=\"Matt.5.39\"></r> (cf. Field, <i>Notes</i>, 40, 105).†</s>"},"G4419":{"l":"πτερύγιον","o":2,"ar":"<f><o>πτερύγιον</o>، <g>-ου, -τό</g></f> <s n=\"1.\"><b>جناح صغير</b>.</s> <s n=\"2.\">كل ما يشبه الجناح، مثل <b>برج صغير</b>، <b>شُرفة</b>: <g>τ. ἱεροῦ</g>، <r v=\"Matt.4.5\"></r>، <r v=\"Luke.4.9\"></r>.†</s>","en":"<f><o>πτερύγιον</o>, <g>-ου, -τό</g></f> <et> <e t=\"derivation\">(dimin. of <g>πτέρυξ</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3671\">כָּנָף</h>;]</e> </et> <s n=\"1.\"><b>a little wing</b>.</s> <s n=\"2.\">Anything like a wing, as <b>a turret</b>, <b>battlement</b>: <g>τ. ἱεροῦ</g>, <r v=\"Matt.4.5\"></r>, <r v=\"Luke.4.9\"></r>.†</s>"},"G4466":{"l":"Ῥαγαύ","o":1,"ar":"<f><o>Ῥαγαύ</o>، <g>ὁ</g>، لا يُصرَّف (في السبعينية ترجمةً للعبرية <h n=\"H7466\">רְעוּ</h>، <r v=\"Gen.11.18\"></r>، وفي مواضع أخرى)، </f> <s><b>رعو</b>: <r v=\"Luke.3.35\"></r>.†</s>","en":"<f><o>Ῥαγαύ</o> (Rec. <g>-αῦ</g>), <g>ὁ</g>, indecl. (LXX for Heb. <h n=\"H7466\">רְעוּ</h>, <r v=\"Gen.11.18\"></r>, al.), </f> <s><b>Reu</b>: <r v=\"Luke.3.35\"></r>.†</s>"},"G4467":{"l":"ῥᾳδιούργημα","o":1,"ar":"<f>* <o>ῥᾳδιούργημα</o>، <g>-τος, τό</g></f> <s n=\"1.\"><b>فعل طائش</b>. </s> <s n=\"2.\"><b>جريمة، خُبث</b>: <r v=\"Acts.18.14\"></r>.†</s>","en":"<f>* <o>ῥᾳδιούργημα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>ῥᾳδιουργέω</g>, <i>to act recklessly or wrongly</i>) </e> </et> <s n=\"1.\"><b>a reckless act</b>. </s> <s n=\"2.\"><b>crime, villany</b>: <r v=\"Acts.18.14\"></r>.†</s>"},"G4497":{"l":"Ῥοβοάμ","o":2,"ar":"<f><o>Ῥοβοάμ</o>، <g>ὁ </g> لا يُصرَّف (العبرية <h n=\"H7346\">רְחַבְעָם</h>)، </f> <s><b>رحبعام</b>: <r v=\"Matt.1.7\"></r>.†</s>","en":"<f><o>Ῥοβοάμ</o>, <g>ὁ </g> indecl. (Heb. <h n=\"H7346\">רְחַבְעָם</h>), </f> <s><b>Rehoboam</b>: <r v=\"Matt.1.7\"></r>.†</s>"},"G4449":{"l":"πυρράζω","o":2,"ar":"<f>† <o>πυρράζω</o></f> <s><b>يكون أحمر كالنار</b>: <r v=\"Matt.16.2\"></r>، <r v=\"Matt.16.3\"></r>.†</s>","en":"<f>† <o>πυρράζω</o></f> <et> <e t=\"derivation\">(&lt; <g>πυρρός</g>),</e> <e t=\"septuagint\">[in LXX, <g>πυρρίζω</g>: <r v=\"Lev.13.19\"></r>, <r v=\"Lev.13.42\"></r> ff. <r v=\"Lev.14.37\"></r> (<h n=\"H125\">אֲדַמְדָּם</h>)*;]</e> </et> <s><b>to be fiery red</b>: <r v=\"Matt.16.2\"></r>, <r v=\"Matt.16.3\"></r>.†</s>"},"G4498":{"l":"Ῥόδη","o":1,"ar":"<f><o>Ῥόδη</o>، <g>-ης, ἡ </g></f> <s><b>رودا</b>: <r v=\"Acts.12.13\"></r>.†</s>","en":"<f><o>Ῥόδη</o>, <g>-ης, ἡ </g></f> <s><b>Rhoda</b>: <r v=\"Acts.12.13\"></r>.†</s>"},"G4461":{"l":"ῥαββεί","o":15,"ar":"<f>*† <o>ῥαββεί</o></f> <s>لقب احترام يُخاطَب به معلمو اليهود: <b>رابي</b> (يا معلم): <r v=\"Matt.23.7\"></r>، <r v=\"Matt.23.8\"></r>؛ عن يوحنا، <r v=\"John.3.26\"></r>؛ عن المسيح، <r v=\"Matt.26.25\"></r>، <r v=\"Matt.26.49\"></r>، <r v=\"Mark.9.5\"></r> <r v=\"Mark.11.21\"></r> <r v=\"Mark.14.45\"></r>، <r v=\"John.1.30\"></r>، <r v=\"John.1.50\"></r> <r v=\"John.3.2\"></r> <r v=\"John.4.31\"></r> <r v=\"John.6.25\"></r> <r v=\"John.9.2\"></r> <r v=\"John.11.8\"></r>؛ <g>κύριε ῥ.</g>: <r v=\"Mark.10.51\"></r>.†</s>","en":"<f>*† <o>ῥαββεί</o> (Rec. <g>-βί</g>, v. WH, <i>App.</i>, 155)</f> <et> <e t=\"derivation\">(Heb. and Aram. <h n=\"H7227\">רַבִּי</h>, <i>my master</i>; v. Dalman, <i>Words</i>, 327, 331 ff.),</e> </et> <s>a title of respectful address to Jewish teachers, <b>Rabbi</b>: <r v=\"Matt.23.7\"></r>, <r v=\"Matt.23.8\"></r>; of John, <r v=\"John.3.26\"></r>; of Christ, <r v=\"Matt.26.25\"></r>, <r v=\"Matt.26.49\"></r>, <r v=\"Mark.9.5\"></r> <r v=\"Mark.11.21\"></r> <r v=\"Mark.14.45\"></r>, <r v=\"John.1.30\"></r>, <r v=\"John.1.50\"></r> <r v=\"John.3.2\"></r> <r v=\"John.4.31\"></r> <r v=\"John.6.25\"></r> <r v=\"John.9.2\"></r> <r v=\"John.11.8\"></r>; <g>κύριε ῥ.</g>, <r v=\"Mark.10.51\"></r> (WH, mg., v.s. <g>ῥαββουνεί</g>).†</s>"},"G4435":{"l":"πυγμή","o":1,"ar":"<f><o>πυγμή</o>، <g>-ῆς, ἡ</g>،</f> <s><b>القبضة</b>: <g>πυγμῇ νίψασθαι τ. χεῖρας</g>: يغسل الأيدي بالقبضة (أي <i>باعتناء</i>، أو <i>إلى المرفق</i>؛ والمعنى الدقيق غير مؤكد): <r v=\"Mark.7.3\"></r>.†</s>","en":"<f><o>πυγμή</o>, <g>-ῆς, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.21.18\"></r>, <r v=\"Isa.58.4\"></r> (<h n=\"H106\">אֶגְרוֹף</h>)*;]</e> </et> <s><b>the fist</b>: <g>πυγμῇ νίψασθαι τ. χεῖρας</g> (T, <g>πυκνά</g>; Vg., Goth., Copt., <l>crebro</l>), to wash the hands with the fist (<i>diligently</i>, R, txt.; <i>up to the elbow</i>, R, mg.; the exact meaning is doubtful; v. Swete, in l.): <r v=\"Mark.7.3\"></r>.†</s>"},"G4445":{"l":"πυρέσσω","o":2,"ar":"<f>* <o>πυρέσσω</o></f> <s><b>كان محمومًا</b> (مصابًا بالحمّى): <r v=\"Matt.8.14\"></r>، <r v=\"Mark.1.3\"></r>.†</s>","en":"<f>* <o>πυρέσσω</o></f> <et><e t=\"derivation\">(&lt; <g>πῦρ</g>),</e></et> <s><b>to be ill of a fever</b>: <r v=\"Matt.8.14\"></r>, <r v=\"Mark.1.3\"></r>.†</s>"},"G4405":{"l":"πρωία","o":2,"ar":"<f><o>πρωία</o>، انظر تحت مدخل <g>πρώιος</g>.</f>","en":"<f><o>πρωία</o>, v.s. <g>πρώιος</g>.</f>"},"G4403":{"l":"πρύμνα","o":3,"ar":"<f>* <o>πρύμνα</o>، <g>-ης, ἡ</g>،</f> <s>أصلاً مؤنث الصفة <g>πρύμνος</g>، <g>-η</g>، <g>-ον</g> (والمقدَّر <g>ναῦς</g>)، <b>المؤخّرة</b> في السفينة، <b>الكوثل</b>: <r v=\"Mark.4.38\"></r>، <r v=\"Acts.27.29\"></r>؛ عكس <g>πρῷρα</g>، <r v=\"Acts.27.41\"></r>.†</s>","en":"<f>* <o>πρύμνα</o>, <g>-ης, ἡ</g>,</f> <s>prop. fem. of adj. <g>πρύμνος</g>, <g>-η</g>, <g>-ον</g>, (sc. <g>ναῦς</g>), <b>the hindmost part</b> of a ship, <b>the stern</b>: <r v=\"Mark.4.38\"></r>, <r v=\"Acts.27.29\"></r>; opp. to <g>πρῷρα</g>, <r v=\"Acts.27.41\"></r>.†</s>"},"G4485":{"l":"ῥῆγμα","o":1,"ar":"<f><o>ῥῆγμα</o>، <g>-τος, τό</g></f> <s n=\"1.\">في الكلاسيكية (وكذلك في السبعينية): <b>كسر، شقّ</b>؛ ثم كنايةً، <b>ما تمزّق</b>. </s> <s n=\"2.\">في العهد الجديد: <b>هدم، خراب</b>: <r v=\"Luke.6.49\"></r>.†</s>","en":"<f><o>ῥῆγμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ῥήγνυμι</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"1Kgs.11.30-1Kgs.11.31\"></r> <r v=\"1Kgs.12.24\"></r>, <r v=\"2Kgs.2.12\"></r> (<h n=\"H7168\">קְרָעִים</h>), <r v=\"Amos.6.12\"></r> A (<h n=\"H1233\">בְּקִיעַ</h>) * ;] </e> </et> <s n=\"1.\">cl. (and so in LXX), <b>a fracture</b>; then by meton., <b>that which is torn</b>. </s> <s n=\"2.\">In NT, <b>ruin</b>: <r v=\"Luke.6.49\"></r>.†</s>"},"G4478":{"l":"Ῥαχήλ","o":1,"ar":"<f><o>Ῥαχήλ</o>، <g>ἡ</g> لا يُصرَّف (العبرية <h n=\"H7354\">רָחֵל</h>)، </f> <s><b>راحيل</b>: <r v=\"Matt.2.18\"></r> <i>(السبعينية)</i>.†</s>","en":"<f><o>Ῥαχήλ</o>, <g>ἡ</g> indecl. (Heb. <h n=\"H7354\">רָחֵל</h>), </f> <s><b>Rachel</b>: <r v=\"Matt.2.18\"></r> <i>(LXX)</i>.†</s>"},"G4462":{"l":"ῥαββουνεί","o":null,"ar":"<f>*† <o>ῥαββουνεί</o> (انظر تحت مدخل <g>ῥαββεί</g>) (بالآرامية <h n=\"H7238\">רַבּוֺנִי</h>، وفيما بعد <h n=\"????\">רִבּוֺנִי</h>، <i>سيدي</i>)؛</f> <s><b>ربوني</b>: <r v=\"Mark.10.51\"></r>، <r v=\"John.20.16\"></r>.†</s>","en":"<f>*† <o>ῥαββουνεί</o> (Rec. <g>-βονί</g>, v.s. <g>ῥαββεί</g>) (Aram. <h n=\"H7238\">רַבּוֺנִי</h>, later, <h n=\"????\">רִבּוֺנִי</h>, <i>my master</i>; on the Greek vocalization and the relation of the word to <g>ῥαββεί</g>, v. Dalman, <i>Words</i>, 324, 340; <i>Gr.</i>, 140<i>n</i>; <i>DB</i>, iv, 190);</f> <s><b>Rabboni</b>: <r v=\"Mark.10.51\"></r> (WH, mg., <g>κύριε ῥαββεί</g>), <r v=\"John.20.16\"></r>.†</s>"},"G4414":{"l":"πρωτοστάτης","o":1,"ar":"<f><o>πρωτοστάτης</o>، <g>-ου, ὁ</g></f> <s>أصلاً، عن الجنود، <b>الواقف أولاً</b>، <b>من في الصف الأول</b>؛ ومن ثم، مجازيًا، <b>زعيم (مقدام)</b>: <r v=\"Acts.24.5\"></r>.†</s>","en":"<f><o>πρωτοστάτης</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>πρῶτος</g>, <g>ἵστημι</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Job.15.24\"></r> AB*;]</e> </et> <s>prop., of soldiers, <b>one who stands first</b>, <b>one in the front rank</b> (Thuc., Xen.); hence, metaph., <b>a leader</b>: <r v=\"Acts.24.5\"></r>.†</s>"},"G4425":{"l":"πτύον","o":2,"ar":"<f>** <o>πτύον</o>، <g>-ου, τό</g>،</f> <s><b>رفش (مِذراة)</b> أو <b>مروحة التذرية</b>: <r v=\"Matt.3.12\"></r>، <r v=\"Luke.3.17\"></r>.†</s>","en":"<f>** <o>πτύον</o>, <g>-ου, τό</g>,</f> <et> <e t=\"septuagint\">[in Sm.: <r v=\"Isa.30.24\"></r>*;]</e> </et> <s><b>a winnowing shovel</b> or <b>fan</b>: <r v=\"Matt.3.12\"></r>, <r v=\"Luke.3.17\"></r>.†</s>"},"G4424":{"l":"Πτολεμαΐς","o":1,"ar":"<f><o>Πτολεμαΐς</o>، <g>-ΐδος, ἡ</g>،</f> <s><b>بتولمايس</b>، مدينة ساحلية في فينيقية: <r v=\"Acts.21.7\"></r>.†</s>","en":"<f><o>Πτολεμαΐς</o>, <g>-ΐδος, ἡ</g>,</f> <s><b>Ptolemais</b>, a maritime city of Phœnicea: <r v=\"Acts.21.7\"></r>.†</s>"},"G4496":{"l":"ῥίπτω","o":8,"ar":"<f><o>ῥίπτω</o> و(<r v=\"Acts.22.23\"></r>) <g>ῥιπτέω</g> (صيغة مقوّاة)، </f> <s n=\"1.\"><b>رمى، طرح، قذف</b>: مع منصوب الشيء، <r v=\"Matt.27.5\"></r>، <r v=\"Acts.27.19\"></r>، <r v=\"Acts.27.29\"></r>؛ مع منصوب الشخص، <r v=\"Matt.15.30\"></r>، <r v=\"Luke.4.35\"></r>؛ المبني للمجهول، <r v=\"Luke.17.2\"></r>؛ اسم الفاعل، <g>ἐριμμένοι</g>، <b>مطروحون، منطرحون</b>: <r v=\"Matt.9.36\"></r>؛ عن الثياب، <b>طرحها عنه</b> (للهرب؛ <g>ὅπλα</g>، <r v=\"1Macc.5.43\"></r>؛ وهكذا فُهمت في الترجمات الإنجليزية في <r v=\"Acts.22.23\"></r>، لكن انظر أدناه). </s> <s n=\"2.\">= <g>ῥιπτάζω</g>، <b>هزّ، قلّب، رمى هنا وهناك</b>: <g>τ. ἱμάτια</g>، <r v=\"Acts.22.23\"></r> (لكن انظر أعلاه).†</s>","en":"<f><o>ῥίπτω</o> and (<r v=\"Acts.22.23\"></r>) <g>ῥιπτέω</g> (strengthened form; v. Veitch, s.v. <g>ῥίπτω</g>, fin.), </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7993\">שׁלךְ</h> hi. ;] </e> </et> <s n=\"1.\"><b>to throw, cast, hurl</b>: c. acc. rei, <r v=\"Matt.27.5\"></r>, <r v=\"Acts.27.19\"></r>, <r v=\"Acts.27.29\"></r>; c. acc. pers., <r v=\"Matt.15.30\"></r>, <r v=\"Luke.4.35\"></r>; pass., <r v=\"Luke.17.2\"></r>; ptcp., <g>ἐριμμένοι</g>, <b>cast down, prostrate</b> (Polyb., al.): <r v=\"Matt.9.36\"></r>; of garments, <b>to throw off</b> (for flight, Eur., Xen., al.; <g>ὅπλα</g>, <r v=\"1Macc.5.43\"></r>; so EV in <r v=\"Acts.22.23\"></r>, but v. infr.). </s> <s n=\"2.\">= <g>ῥιπτάζω</g>, <b>to shake, toss, throw about</b>: <g>τ. ἱμάτια</g>, <r v=\"Acts.22.23\"></r> (<i>EGT</i>, Page, Rackham, in l.; Field, <i>Notes</i>, 136; but v. supr.).†</s>"},"G4471":{"l":"Ῥαμά","o":1,"ar":"<f><o>Ῥαμά</o>، <g>ἡ</g>، لا يُصرَّف (بالعبرية <h n=\"H7414\">רָמָה</h>)، </f> <s><b>الرامة</b>: <r v=\"Matt.2.18\"></r> <i>(السبعينية)</i>.†</s>","en":"<f><o>Ῥαμά</o> (Rec. <g>-ᾶ</g>), <g>ἡ</g>, indecl. (Heb. <h n=\"H7414\">רָמָה</h>), </f> <s><b>Ramah</b>: <r v=\"Matt.2.18\"></r> <i>(LXX)</i>.†</s>"},"G4499":{"l":"Ῥόδος","o":1,"ar":"<f><o>Ῥόδος</o>، <g>-ου, ὁ </g></f> <s>جزيرة <b>رودس</b>: <r v=\"Acts.21.1\"></r>.†</s>","en":"<f><o>Ῥόδος</o>, <g>-ου, ὁ </g></f> <s>the island of <b>Rhodes</b>: <r v=\"Acts.21.1\"></r>.†</s>"},"G4436":{"l":"πύθων","o":1,"ar":"<f>* <o>πύθων</o>، <g>-ωνος, ὁ</g>،</f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>بيثون</b>، حيّة قتلها أبولو، ولذلك لُقّب بالبيثي.</s> <s n=\"2.\">عند الكتّاب المتأخرين: اسم أُطلق على العرّافين الذين يتكلمون من بطونهم (<g>ἐγγαστρίμυθοι</g>؛ قارن <r v=\"Lev.19.31\"></r> <r v=\"Lev.20.6\"></r>، <r v=\"Lev.20.27\"></r>، <r v=\"1Sam.28.7\"></r>)، وربما بهذا المعنى <g>πνεῦμα πύθωνα</g>، <b>روح بيثون (روح عرافة)</b>: <r v=\"Acts.16.16\"></r>.†</s>","en":"<f>* <o>πύθων</o>, <g>-ωνος, ὁ</g>,</f> <s n=\"1.\">in cl., <b>Python</b>, a serpent slain by Apollo, who is hence surnamed the Pythian.</s> <s n=\"2.\">In Plut. (ii, 414 E), a name given to ventriloquist soothsayers (<g>ἐγγαστρίμυθοι</g>; cf. <r v=\"Lev.19.31\"></r> <r v=\"Lev.20.6\"></r>, <r v=\"Lev.20.27\"></r>, <r v=\"1Sam.28.7\"></r>), and perhaps in this sense <g>πνεῦμα πύθωνα</g>, <b>a python-spirit</b>: <r v=\"Acts.16.16\"></r>.†</s>"},"G4468":{"l":"ῥᾳδιουργία","o":1,"ar":"<f>* <o>ῥᾳδιουργία</o>، <g>-ας, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>سهولة في العمل، يُسر</b>. </s> <s n=\"2.\">في الكلاسيكية: <b>تهاون، كسل</b>. </s> <s n=\"3.\"><b>طيش، شرّ، خبث</b>: <r v=\"Acts.13.10\"></r>.†</s>","en":"<f>* <o>ῥᾳδιουργία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(v.s. <g>ῥᾳδιούργημα</g>), </e> </et> <s n=\"1.\"><b>ease in doing, facility</b> (Xen.). </s> <s n=\"2.\"><b>easiness, laziness</b> (Xen.). </s> <s n=\"3.\"><b>recklessness, wickedness</b> (of lewdness, Xen.; fraud, Plut.; in <g>π.</g>, of theft, MM, xxii): <r v=\"Acts.13.10\"></r>.†</s>"},"G4401":{"l":"προχειροτονέω","o":1,"ar":"<f>* <o>προ-χειρο-τονέω</o>، <g>-ῶ</g></f> <s><b>اختار</b> أو <b>عيّن مسبقًا</b>: <r v=\"Acts.10.41\"></r>.†</s>","en":"<f>* <o>προ-χειρο-τονέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(v. <g>χειροτονέω</g>),</e> </et> <s><b>to choose</b> or <b>appoint beforehand</b>: <r v=\"Acts.10.41\"></r> (Plat., al.).†</s>"},"G4418":{"l":"πτέρνα","o":1,"ar":"<f><o>πτέρνα</o>، <g>-ης, ἡ</g>،</f> <s><b>العقب</b>: مجازيًا، <g>ἐπαίρειν τὴν π. ἐπί</g>، <r v=\"John.13.18\"></r><i>(السبعينية)</i>.†</s>","en":"<f><o>πτέρνα</o>, <g>-ης, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6119\">עָקֵב</h>;]</e> </et> <s><b>the heel</b>: fig., <g>ἐπαίρειν τὴν π. ἐπί</g>, <r v=\"John.13.18\"></r><i>(LXX)</i>.†</s>"},"G4488":{"l":"Ῥησά","o":1,"ar":"<f><o>Ῥησά</o>، <g>ὁ</g></f> <s>لا يُصرَّف، </s> <s><b>ريسا:</b> <r v=\"Luke.3.27\"></r>.†</s>","en":"<f><o>Ῥησά</o> (L, <g>-σᾶ</g>), <g>ὁ</g></f> <s>indecl., </s> <s><b>Rhesa:</b> <r v=\"Luke.3.27\"></r>.†</s>"},"G4402":{"l":"Πρόχορος","o":1,"ar":"<f><o>Πρόχορος</o>، <g>-ου, ὁ</g>،</f> <s><b>بروخورس</b>: <r v=\"Acts.6.5\"></r>.</s>","en":"<f><o>Πρόχορος</o>, <g>-ου, ὁ</g>,</f> <s><b>Prochorus</b>: <r v=\"Acts.6.5\"></r>.</s>"},"G4477":{"l":"Ῥαχάβ","o":1,"ar":"<f><o>Ῥαχάβ</o>، انظر تحت مدخل <g>Ραάβ</g>.</f>","en":"<f><o>Ῥαχάβ</o>, v.s. <g>Ραάβ</g>.</f>"},"G4495":{"l":"ῥιπτέω","o":1,"ar":"<f><o>ῥιπτέω</o>، انظر تحت مدخل <g>ῥίπτω</g>.</f>","en":"<f><o>ῥιπτέω</o>, v.s. <g>ῥίπτω</g>.</f>"},"G4454":{"l":"πῶλος","o":12,"ar":"<f><o>πῶλος</o>، <g>-ου, ὁ</g></f> <s><b>جحش</b>، <b>مُهر</b>، أصلاً ولد الفرس، ثم صغار الحيوانات الأخرى؛ وفي العهد الجديد عن جحش الأتان: <r v=\"Matt.21.2\"></r>، <r v=\"Matt.21.5\"></r> <i>(السبعينية)</i>، <r v=\"Matt.21.7\"></r>، <r v=\"Mark.11.2\"></r>، <r v=\"Mark.11.4\"></r>، <r v=\"Mark.11.5\"></r>، <r v=\"Mark.11.7\"></r>، <r v=\"Luke.19.30\"></r>، <r v=\"Luke.19.33\"></r>، <r v=\"Luke.19.35\"></r>، <r v=\"John.12.15\"></r> <i>(السبعينية)</i>.†</s>","en":"<f><o>πῶλος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(in cl. also <g>ἡ</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5895\">עַיִר</h>;]</e> </et> <s><b>a foal</b>, <b>colt</b>, prop., of a horse, then the young of other animals; in NT of the colt of an ass: <r v=\"Matt.21.2\"></r>, <r v=\"Matt.21.5\"></r><i>(LXX)</i>, <r v=\"Matt.21.7\"></r>, <r v=\"Mark.11.2\"></r>, <r v=\"Mark.11.4\"></r>, <r v=\"Mark.11.5\"></r>, <r v=\"Mark.11.7\"></r>, <r v=\"Luke.19.30\"></r>, <r v=\"Luke.19.33\"></r>, <r v=\"Luke.19.35\"></r>, <r v=\"John.12.15\"></r><i>(LXX)</i>.†</s>"},"G4400":{"l":"προχειρίζω","o":3,"ar":"<f><o>προ-χειρίζω</o></f> <s n=\"1.\"><b>وضع في اليد</b>، <b>سلّم</b>: المبني للمجهول، <r v=\"Acts.3.20\"></r>.</s> <s n=\"2.\">وكثيرًا فعلًا لازم الصيغة الوسطى، <g>-ομαι</g>، <b>أخذ في يده</b>؛ ومن ثم مجازيًا، <b>عزم</b>، <b>عيّن</b>، <b>اختار</b>: مع المصدر، <r v=\"Acts.22.14\"></r>؛ مع منصوب الشخص، <r v=\"Acts.26.16\"></r>.†</s>","en":"<f><o>προ-χειρίζω</o></f> <et> <e t=\"derivation\">(&lt; <g>πρόχειρος</g>, <i>at hand</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Exod.4.13\"></r> (<h n=\"H7971\">שׁלח</h>), <r v=\"Josh.3.12\"></r> (<h n=\"H3947\">לקח</h>), <r v=\"Dan.3.22\"></r>, <r v=\"2Macc.3.7\"></r> <r v=\"2Macc.8.9\"></r> <r v=\"2Macc.14.12\"></r> A*;]</e> </et> <s n=\"1.\"><b>to put into the hand</b>, <b>deliver up</b>: pass., <r v=\"Acts.3.20\"></r>.</s> <s n=\"2.\">More freq. as depon., <g>-ομαι</g>, <b>to take into one's hand</b>; hence, metaph., <b>to propose</b>, <b>determine</b>, <b>choose</b>: c. inf., <r v=\"Acts.22.14\"></r>; c. acc. pers., <r v=\"Acts.26.16\"></r>.†</s>"},"G4446":{"l":"πυρετός","o":6,"ar":"<f><o>πυρετός</o>، <g>-οῦ, ὁ</g></f> <s><b>حمّى</b>: <r v=\"Matt.8.15\"></r>، <r v=\"Mark.1.31\"></r>، <r v=\"Luke.4.39\"></r>، <r v=\"John.4.52\"></r>، <r v=\"Acts.28.8\"></r>؛ <g>π. μέγας</g>، <b>حمّى شديدة</b>: <r v=\"Luke.4.38\"></r>.†</s>","en":"<f><o>πυρετός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>πῦρ</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Deut.28.22\"></r> (<h n=\"H6920\">קדַּחַת</h>)*;]</e> </et> <s><b>a fever</b>: <r v=\"Matt.8.15\"></r>, <r v=\"Mark.1.31\"></r>, <r v=\"Luke.4.39\"></r>, <r v=\"John.4.52\"></r>, <r v=\"Acts.28.8\"></r>; <g>π. μέγας</g>, <b>a high fever</b>: <r v=\"Luke.4.38\"></r> (on the technical phrase here, v. MM, xxii).†</s>"},"G4408":{"l":"πρῷρα","o":2,"ar":"<f>* <o>πρῷρα</o>، <g>-ης</g>، <g>ἡ</g>،</f> <s>الجزء الأمامي من السفينة، <b>المقدَّم</b>: <r v=\"Acts.27.30\"></r>؛ عكس <g>πρύμνα</g>، <r v=\"Acts.27.41\"></r>.†</s>","en":"<f>* <o>πρῷρα</o> (Rec. incorrectly <g>πρώρα</g>, v. Bl., § 3, 3; LS, s.v.), <g>-ης</g> (for Att. <g>-ας</g>, v. Bl., § 7, 1; Mayser, l 2), <g>ἡ</g>,</f> <s>the forward part of a ship, <b>the prow</b>: <r v=\"Acts.27.30\"></r>; opp. to <g>πρύμνα</g>, <r v=\"Acts.27.41\"></r>.†</s>"},"G4411":{"l":"πρωτοκλυτία","o":5,"ar":"<f>*† <o>πρωτο-κλισία</o>، <g>-ας, ἡ</g>،</f> <s><b>المتكأ الأول</b> على المائدة (قارن <r v=\"Mark.12.39\"></r>): <r v=\"Matt.23.6\"></r>، <r v=\"Mark.12.39\"></r>، <r v=\"Luke.14.7\"></r>، <r v=\"Luke.14.8\"></r>، <r v=\"Luke.20.46\"></r>.†</s>","en":"<f>*† <o>πρωτο-κλισία</o>, <g>-ας, ἡ</g>,</f> <s><b>the chief place</b> at table (v. Swete, <r v=\"Mark.12.39\"></r>): <r v=\"Matt.23.6\"></r>, <r v=\"Mark.12.39\"></r>, <r v=\"Luke.14.7\"></r>, <r v=\"Luke.14.8\"></r> <r v=\"Luke.20.46\"></r>.†</s>"},"G4422":{"l":"πτοέω","o":2,"ar":"<f><o>πτοέω</o>، <g>-ῶ</g>،</f> <s><b>أرعب</b>. المبني للمجهول، <b>ارتعب، فزع</b>: <r v=\"Luke.21.9\"></r>، <r v=\"Luke.24.37\"></r>.†</s>","en":"<f><o>πτοέω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2865\">חתת</h> ni.;]</e> </et> <s><b>to terrify</b>. Pass., <b>to be terrified</b>: <r v=\"Luke.21.9\"></r> <r v=\"Luke.24.37\"></r> (WH, mg., <g>θροηθέντες</g>).†</s>"},"G4427":{"l":"πτύσμα","o":1,"ar":"<f>* <o>πτύσμα</o>، <g>-τος, τό</g>،</f> <s><b>تفل، بُصاق</b>: <r v=\"John.9.6\"></r>.†</s>","en":"<f>* <o>πτύσμα</o>, <g>-τος, τό</g>,</f> <et> <e t=\"derivation\">(&lt; <g>πτύω</g>),</e> </et> <s><b>spittle</b>: <r v=\"John.9.6\"></r> (Hipp., Polyb., al.).†</s>"},"G4443":{"l":"πυρά","o":2,"ar":"<f>** <o>πυρά</o>، <g>-ᾶς, ἡ</g></f> <s><b>نار</b>: <r v=\"Acts.28.2\"></r>، <r v=\"Acts.28.3\"></r>.†</s>","en":"<f>** <o>πυρά</o>, <g>-ᾶς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>πῦρ</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Jdt.7.5\"></r>, <r v=\"Wis.17.6\"></r>, al.;]</e> </et> <s><b>a fire</b>: <r v=\"Acts.28.2\"></r>, <r v=\"Acts.28.3\"></r>.†</s>"},"G4484":{"l":"Ῥήγιον","o":1,"ar":"<f><o>Ῥήγιον</o>، <g>-ου, τό </g></f> <s><b>ريغيون</b>، بلدة في صقلية: <r v=\"Acts.28.13\"></r>.†</s>","en":"<f><o>Ῥήγιον</o>, <g>-ου, τό </g></f> <s><b>Rhegium</b>, a town in Sicily: <r v=\"Acts.28.13\"></r>.†</s>"}});A.got[44]=1})(window.ABBOTT=window.ABBOTT||{D:{},got:{}});